# ================================================================
#  مخزن داده و ذخیره‌سازی
# ================================================================
DATA: dict[str, Any] = {}
LOCK = threading.RLock()
LAST_SAVE = 0.0
SAVED_ONCE = {"v": False}


def now_ts() -> int:
    return int(time.time())


def default_data() -> dict[str, Any]:
    return {
        "schema": 3,
        "users": {},
        "groups": {},
        "games": {},
        "broadcast_log": [],
        "audit": [],
        "settings": {
            "max_players_default": 20,
            "adult_default": False,
            "xp_multiplier": 1,
            "coins_multiplier": 1,
        },
    }


def merge_defaults(target: dict, template: dict) -> None:
    for key, value in template.items():
        if key not in target:
            target[key] = deepcopy(value)
        elif isinstance(value, dict) and isinstance(target[key], dict):
            merge_defaults(target[key], value)


def load_data() -> dict:
    data = default_data()
    try:
        with open(DATA_FILE, "r", encoding="utf-8") as f:
            raw = json.load(f)
        if isinstance(raw, dict):
            data.update(raw)
    except FileNotFoundError:
        pass
    except Exception as exc:
        print(f"ApexRival data warning: could not read {DATA_FILE!r} ({exc!r}); starting with defaults")
    data.setdefault("users", {})
    data.setdefault("groups", {})
    data.setdefault("games", {})
    data.setdefault("audit", [])
    data.setdefault("broadcast_log", [])
    data.setdefault("global_content", {})
    data.setdefault("settings", {})
    merge_defaults(data["settings"], default_data()["settings"])
    for user in data["users"].values():
        if not isinstance(user, dict):
            continue
        merge_defaults(user, DEFAULT_USER)
        if not isinstance(user.get("inventory"), dict):
            user["inventory"] = {}
        merge_defaults(user["inventory"], DEFAULT_USER["inventory"])
        if not isinstance(user.get("stats"), dict):
            user["stats"] = {}
        merge_defaults(user["stats"], DEFAULT_USER["stats"])
    for group in data["groups"].values():
        if not isinstance(group, dict):
            continue
        merge_defaults(group, DEFAULT_GROUP)
        merge_defaults(group["settings"], DEFAULT_GROUP["settings"])
        group.setdefault("content", {})
    return data


DATA = load_data()


def save_data(force: bool = False) -> None:
    """ذخیره‌ی اتمی و سریع داده‌ها (JSON فشرده، تعویض اتمی فایل)."""
    global LAST_SAVE
    current = time.time()
    if not force and current - LAST_SAVE < SAVE_EVERY_SECONDS:
        return
    tmp = DATA_FILE + ".tmp"
    with LOCK:
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(DATA, f, ensure_ascii=False, separators=(",", ":"))
            os.replace(tmp, DATA_FILE)
            LAST_SAVE = current
            SAVED_ONCE["v"] = True
        except Exception as exc:
            print(f"ApexRival save warning: {exc!r}")


def audit(action: str, actor: int, chat_id: int | None = None, details: str = "") -> None:
    with LOCK:
        DATA["audit"].append({
            "ts": now_ts(),
            "action": action,
            "actor": int(actor),
            "chat_id": int(chat_id) if chat_id else None,
            "details": str(details)[:500],
        })
        if len(DATA["audit"]) > 4000:
            DATA["audit"] = DATA["audit"][-2000:]


# -----------------------------
#  بکاپ خودکار (هر ۶ ساعت + بکاپ هنگام بوت)
# -----------------------------
def backup_data(reason: str = "auto") -> str | None:
    try:
        Path(BACKUP_DIR).mkdir(parents=True, exist_ok=True)
        stamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
        path = os.path.join(BACKUP_DIR, f"apexrival_{reason}_{stamp}.json")
        with LOCK:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(DATA, f, ensure_ascii=False, separators=(",", ":"))
        # فقط ۲۰ بکاپ آخر نگه داشته شود
        files = sorted(Path(BACKUP_DIR).glob("apexrival_*.json"), key=lambda p: p.stat().st_mtime, reverse=True)
        for old in files[20:]:
            try:
                old.unlink()
            except Exception:
                pass
        return path
    except Exception as exc:
        print(f"ApexRival backup warning: {exc!r}")
        return None


def list_backups():
    try:
        return sorted(Path(BACKUP_DIR).glob("apexrival_*.json"), key=lambda p: p.stat().st_mtime, reverse=True)
    except Exception:
        return []


# ================================================================
#  بانک سوالات — بارگذاری + اعمال تغییرات ذخیره‌شده‌ی ادمین
# ================================================================
BANKS: dict[str, list[str]] = {k: list(v) for k, v in BANKS_FACTORY.items()}
BANKS_PERSIST_VERSION = 1


def bank_hash(text: str) -> str:
    return hashlib.sha256(str(text).encode("utf-8")).hexdigest()[:16]


def editor_store() -> dict:
    """مخزن ویرایش بانک داخل DATA — با ری‌استارت نمی‌پرد."""
    s = DATA.setdefault("v18_stores", {})
    s.setdefault("overrides", {})   # {bank_key: {orig_hash: new_text}}
    s.setdefault("disabled", {})    # {bank_key: [{"h": hash, "text": original}]}
    s.setdefault("topics_off", [])  # کلید موضوعات خاموش
    s.setdefault("heat", {"t2": 4, "t3": 8})
    s.setdefault("stats", {"banks": {}, "heat": {}, "quests_done": 0, "edits": 0, "adds": 0})
    return s


def apply_bank_admin_changes() -> None:
    """تغییرات ذخیره‌شده‌ی ادمین (سوال سفارشی/ویرایش/حذف/موضوع خاموش) را
    روی بانک زنده اعمال می‌کند. هر بار بعد از تغییر مدیریتی هم اجرا می‌شود."""
    st = editor_store()
    # ۱) سوالات سفارشی V16 و V18
    for store_key in ("v16_custom_prompts", "v18_custom_prompts"):
        customs = DATA.get(store_key, {})
        if isinstance(customs, dict):
            for key, items in customs.items():
                if not isinstance(items, list):
                    continue
                bank = BANKS.setdefault(str(key), [])
                existing = set(bank)
                for raw in items:
                    text = str(raw).strip()
                    if text and text not in existing:
                        bank.append(text)
                        existing.add(text)
    # ۲) ویرایش‌ها (override بر اساس هش متن اصلی)
    overrides = st.get("overrides", {})
    for key, mapping in overrides.items():
        if not isinstance(mapping, dict):
            continue
        bank = BANKS.get(str(key))
        if not bank:
            continue
        hashes = {bank_hash(x): i for i, x in enumerate(bank)}
        for orig_h, new_text in mapping.items():
            idx = hashes.get(str(orig_h))
            if idx is not None and str(new_text).strip():
                bank[idx] = str(new_text).strip()
    # ۳) حذف‌شده‌ها
    disabled = st.get("disabled", {})
    for key, items in disabled.items():
        if not isinstance(items, list):
            continue
        bank = BANKS.get(str(key))
        if not bank:
            continue
        removed = {str(e.get("h")) for e in items if isinstance(e, dict)}
        BANKS[str(key)] = [x for x in bank if bank_hash(x) not in removed]
    # ۴) موضوعات خاموش فقط در منو اثر دارند؛ بانک دست‌نخورده می‌ماند


apply_bank_admin_changes()


def topics_off() -> list:
    return editor_store().get("topics_off", [])


def heat_conf() -> dict:
    h = editor_store().get("heat", {})
    return {"t2": max(1, int(h.get("t2", 4) or 4)), "t3": max(2, int(h.get("t3", 8) or 8))}


def game_heat(game: dict) -> int:
    """گرمای بازی از روی تعداد سوال‌های پرسیده‌شده (۱=آرام ۲=داغ ۳=آتیشی)."""
    try:
        conf = heat_conf()
        t2 = max(1, int(conf.get("t2", 4)))
        t3 = max(t2 + 1, int(conf.get("t3", 8)))
        asked = int(game.get("round", 0) or 0) + 1
        if asked >= t3:
            return 3
        if asked >= t2:
            return 2
        return 1
    except Exception:
        return 1


def heat_chip(heat: int) -> str:
    return HEAT_LABELS.get(int(heat), HEAT_LABELS[1])


def heat_window(bank: list, heat: int) -> list:
    """برش پنجره‌ی گرمایی از بانک مرتب‌شده (آرام → آتیشی)."""
    n = len(bank)
    if n == 0:
        return []
    if n <= 3:
        return list(bank)
    third = max(1, n // 3)
    if heat <= 1:
        return bank[:third]
    if heat == 2:
        return bank[third:2 * third]
    return bank[2 * third:]


def pick_question(game: dict, category: str, target_uid: int | None = None) -> str:
    """انتخاب سوال با موتور گرما + تاریخچه مصرف + روتینگ جنسیت ۱۸+."""
    bank = list(BANKS.get(category, []))
    if category == "adult" and target_uid is not None:
        gender = user_gender(int(target_uid))
        if gender == "male":
            bank = list(BANKS.get("adult_male", [])) + list(BANKS.get("adult", []))
        elif gender == "female":
            bank = list(BANKS.get("adult_female", [])) + list(BANKS.get("adult", []))
    if not bank:
        return "برای این حالت هنوز محتوایی ثبت نشده است."
    used = set(game.setdefault("v7_used_prompts_global", []))
    heat = game_heat(game)
    choices = [x for x in heat_window(bank, heat) if x not in used]
    if not choices:
        choices = [x for x in bank if x not in used]
    if not choices:
        used.clear()
        game["v7_used_prompts_global"] = []
        choices = heat_window(bank, heat) or list(bank)
        if not choices:
            return "🎲 این دسته برای این بازی کاملاً مصرف شده است؛ حالت دیگری را انتخاب کن."
    item = random.choice(choices)
    used.add(item)
    game["v7_used_prompts_global"] = list(used)[-2000:]
    try:
        stats = editor_store()["stats"]
        stats["banks"][category] = int(stats["banks"].get(category, 0)) + 1
        stats["heat"][str(heat)] = int(stats["heat"].get(str(heat), 0)) + 1
    except Exception:
        pass
    return item


def pick_penalty(game: dict) -> str:
    bank = BANKS.get("penalty", [])
    used = set(game.setdefault("v7_used_penalties", []))
    choices = [x for x in bank if x not in used]
    if not choices:
        used.clear()
        choices = list(bank)
    if not choices:
        return "یک کار خیر انجام بده و به خودت جایزه بده! 🎁"
    item = random.choice(choices)
    used.add(item)
    game["v7_used_penalties"] = list(used)
    return item


# ================================================================
#  کاربران، سطح، XP و سکه
# ================================================================
def user_key(uid: int) -> str:
    return str(uid)


def group_key(cid: int) -> str:
    return str(cid)


def get_user(uid: int, name: str | None = None) -> dict:
    with LOCK:
        user = DATA["users"].setdefault(user_key(uid), deepcopy(DEFAULT_USER))
        if user.get("created_at", 0) == 0:
            user["created_at"] = now_ts()
        if name:
            user["name"] = name
        merge_defaults(user, DEFAULT_USER)
        # نرمال‌سازی دفاعی (داده‌ی قدیمی/خراب هرگز باعث کرش نمی‌شود)
        try:
            user["xp"] = max(0, int(user.get("xp", 0) or 0))
            user["coins"] = max(0, int(user.get("coins", 0) or 0))
            user["level"] = level_for_xp(user["xp"])
        except Exception:
            user["xp"] = max(0, int(user.get("xp", 0) or 0)) if str(user.get("xp", "0")).lstrip("-").isdigit() else 0
            user["coins"] = 0
            user["level"] = 1
        if not isinstance(user.get("achievements"), list):
            user["achievements"] = []
        if not isinstance(user.get("inventory"), dict):
            user["inventory"] = {}
        merge_defaults(user["inventory"], DEFAULT_USER["inventory"])
        if not isinstance(user.get("stats"), dict):
            user["stats"] = {}
        merge_defaults(user["stats"], DEFAULT_USER["stats"])
        return user


def get_group(chat_id: int) -> dict:
    with LOCK:
        group = DATA["groups"].setdefault(group_key(chat_id), deepcopy(DEFAULT_GROUP))
        merge_defaults(group, DEFAULT_GROUP)
        merge_defaults(group["settings"], DEFAULT_GROUP["settings"])
        group.setdefault("content", {})
        return group


def is_admin(uid: int) -> bool:
    return bool(ADMIN_ID and int(uid) == int(ADMIN_ID))


def is_banned(uid: int) -> bool:
    try:
        return bool(DATA["users"].get(user_key(uid), {}).get("banned", False))
    except Exception:
        return False


def level_for_xp(xp: int) -> int:
    return max(1, min(100, 1 + int(xp) // 100))


def title_for(xp: int) -> str:
    if xp >= 2500:
        return "👑 Apex Legend"
    if xp >= 1500:
        return "🔥 سلطان میدان"
    if xp >= 900:
        return "⚔️ رقیب نخبه"
    if xp >= 500:
        return "💀 کابوس گروه"
    if xp >= 250:
        return "🎯 بازیکن حرفه‌ای"
    if xp >= 100:
        return "🧨 دردسرساز"
    if xp >= 50:
        return "⭐ رقیب جوان"
    return "🌱 تازه‌وارد"


def add_xp(uid: int, amount: int, name: str = "کاربر", group_mult: int = 1) -> int:
    """XP با احتساب بوست فروشگاه و ضریب گروه. خروجی: تعداد سطح ارتقا."""
    user = get_user(uid, name)
    try:
        amount = max(0, int(amount))
    except Exception:
        amount = 0
    try:
        if amount > 0 and user.get("v24_xp_until", 0) and time.time() < float(user.get("v24_xp_until", 0)):
            amount = amount * 2
    except Exception:
        pass
    try:
        amount = int(amount * event_multiplier("xp"))
    except Exception:
        pass
    amount = amount * max(1, int(group_mult))
    before_level = level_for_xp(int(user["xp"]))
    user["xp"] = max(0, int(user["xp"]) + amount)
    user["level"] = level_for_xp(int(user["xp"]))
    after_level = user["level"]
    try:
        season_add_xp(int(uid), amount)
        monthly_record_xp(int(uid), amount)
        adv_track(int(uid), "xp", {"amount": amount})
    except Exception:
        pass
    try:
        if after_level > before_level:
            adv_on_level(int(uid), before_level, after_level)
    except Exception:
        pass
    check_achievements(uid)
    try:
        weekly_record_xp(int(uid), amount)
    except Exception:
        pass
    try:
        team_credit(int(uid), amount)
    except Exception:
        pass
    return after_level - before_level


def add_coins(uid: int, amount: int, name: str = "کاربر", group_mult: int = 1) -> None:
    user = get_user(uid, name)
    try:
        amount = int(amount)
    except Exception:
        amount = 0
    try:
        if amount > 0 and user.get("v24_luck_until", 0) and time.time() < float(user.get("v24_luck_until", 0)):
            amount = amount * 2
    except Exception:
        pass
    try:
        amount = int(amount * event_multiplier("coins"))
    except Exception:
        pass
    amount = amount * max(1, int(group_mult))
    user["coins"] = max(0, int(user["coins"]) + amount)
    try:
        if amount > 0:
            adv_track(int(uid), "coins", {"amount": amount})
    except Exception:
        pass
    check_achievements(uid)


def spend_coins(uid: int, amount: int) -> bool:
    user = get_user(uid)
    amount = max(0, int(amount))
    if int(user["coins"]) < amount:
        return False
    user["coins"] -= amount
    return True


def inventory(uid: int) -> dict:
    inv = get_user(uid)["inventory"]
    if not isinstance(inv, dict):
        inv = {}
        get_user(uid)["inventory"] = inv
    return inv


def grant_item(uid: int, item: str, amount: int = 1) -> None:
    inv = inventory(uid)
    inv[item] = int(inv.get(item, 0)) + int(amount)


def user_gender(uid: int) -> str:
    try:
        return str(DATA["users"].get(user_key(uid), {}).get("gender", "") or "")
    except Exception:
        return ""


def gender_icon(uid: int) -> str:
    g = user_gender(uid)
    if g == "male":
        return "👦"
    if g == "female":
        return "👧"
    return ""


def name_of(uid: int, game: dict | None = None) -> str:
    """نام نمایشی بازیکن (از بازی، وگرنه از داده‌ی کاربر)."""
    try:
        if game is not None:
            names = game.get("names", {})
            if names:
                n = names.get(str(uid)) or names.get(int(uid))
                if n:
                    return str(n)
    except Exception:
        pass
    try:
        return str(DATA["users"].get(user_key(uid), {}).get("name") or "بازیکن")
    except Exception:
        return "بازیکن"


def user_is_muted(uid: int) -> bool:
    try:
        return bool(v19_prefs(int(uid)).get("mute", False))
    except Exception:
        return False


def mention_user(uid: int, name: str | None = None) -> str:
    """منشن امن: اگر کاربر mute کرده باشد بدون لینک، اگر BRB باشد با 🌙."""
    label = str(name or name_of(uid))
    if user_is_muted(int(uid)):
        return escape(label)
    moon = ""
    try:
        if is_brb(int(uid)):
            moon = " 🌙"
    except Exception:
        pass
    return f'<a href="tg://user?id={int(uid)}">{escape(label)}</a>{moon}'


def check_achievements(uid: int) -> None:
    """دستاوردها را چک می‌کند و در صورت دستیابی، سکه جایزه می‌دهد."""
    user = get_user(uid)
    got = user.setdefault("achievements", [])
    newly: list[tuple[str, int]] = []
    xp = int(user.get("xp", 0))
    checks = {
        "first_win": int(user.get("wins", 0)) >= 1,
        "ten_wins": int(user.get("wins", 0)) >= 10,
        "streak5": int(user.get("best_streak", 0)) >= 5,
        "coins100": int(user.get("coins", 0)) >= 100,
        "xp500": xp >= 500,
        "games20": int(user.get("games", 0)) >= 20,
        "missions10": int(user.get("missions", 0)) >= 10,
        "boss5": int(user.get("boss", 0)) >= 5,
        "duels10": int(user.get("duels", 0)) >= 10,
        "votes10": int(user.get("votes", 0)) >= 10,
    }
    for key, ok in checks.items():
        if ok and key not in got:
            got.append(key)
            newly.append((key, ACHIEVEMENTS_BASE.get(key, ("", "", 0))[2]))
    for key, coins in newly:
        if coins:
            user["coins"] = int(user.get("coins", 0)) + int(coins)


def award_achievement(uid: int, key: str) -> bool:
    """دستاورد رویدادی (غیر از آستانه‌های آماری)."""
    try:
        adv_track(int(uid), "ach", {})
    except Exception:
        pass
    if key not in ACHIEVEMENTS_BASE:
        return False
    user = get_user(uid)
    got = user.setdefault("achievements", [])
    if key in got:
        return False
    got.append(key)
    coins = ACHIEVEMENTS_BASE.get(key, ("", "", 0))[2]
    if coins:
        user["coins"] = int(user.get("coins", 0)) + int(coins)
    return True


