# ================================================================
#  دکتر داده — تعمیر خودکار داده‌های کهنه/خراب هنگام بوت
# ================================================================
def data_doctor() -> list:
    """تعمیر ساختاری داده‌ها هنگام بوت؛ فهرست اصلاحات را برمی‌گرداند."""
    fixes: list[str] = []
    try:
        # ۱) کاربران
        for key, user in list(DATA.get("users", {}).items()):
            if not isinstance(user, dict):
                DATA["users"].pop(key, None)
                fixes.append(f"user-drop:{key}")
                continue
            try:
                user["xp"] = max(0, int(user.get("xp", 0) or 0))
                user["coins"] = max(0, int(user.get("coins", 0) or 0))
                user["level"] = level_for_xp(user["xp"])
                if not isinstance(user.get("achievements"), list):
                    user["achievements"] = []
                if not isinstance(user.get("inventory"), dict):
                    user["inventory"] = {}
                if not isinstance(user.get("stats"), dict):
                    user["stats"] = {}
            except Exception:
                pass
        # ۲) گروه‌ها
        for key, group in list(DATA.get("groups", {}).items()):
            if not isinstance(group, dict):
                DATA["groups"].pop(key, None)
                fixes.append(f"group-drop:{key}")
                continue
            gid = int(key) if str(key).lstrip("-").isdigit() else 0
            if gid < 0:
                group["min_players"] = max(2, min(20, int(group.get("min_players", 2) or 2)))
                group["max_players"] = max(group["min_players"], min(30, int(group.get("max_players", 20) or 20)))
        # ۳) بازی‌های معلق — فقط بازی‌های فعال سالم نگه داشته می‌شوند
        for key, game in list(DATA.get("games", {}).items()):
            if not isinstance(game, dict):
                DATA["games"].pop(key, None)
                fixes.append(f"game-drop:{key}")
                continue
            try:
                started = float(game.get("started_at", 0) or 0)
                status = str(game.get("status", ""))
                auto_min = int(game.get("settings", {}).get("auto_end_minutes", 90) or 90)
                if status == "active" and started and (time.time() - started) > (auto_min + 120) * 60:
                    game["status"] = "finished"
                    game["finish_reason"] = "doctor-auto-end"
                    fixes.append(f"game-end:{key}")
                if status in ("active",) and not game.get("players"):
                    game["status"] = "finished"
                    game["finish_reason"] = "doctor-empty"
                    fixes.append(f"game-empty:{key}")
            except Exception:
                pass
        # ۴) اشاره‌ی گروه به بازیِ ناتمام
        for key, group in DATA.get("groups", {}).items():
            if not isinstance(group, dict):
                continue
            ag = group.get("active_game")
            if ag and isinstance(ag, str):
                g = DATA.get("games", {}).get(ag)
                if not isinstance(g, dict) or str(g.get("status")) != "active":
                    group["active_game"] = None
                    fixes.append(f"group-unlink:{key}")
        # ۵) مجازات‌های معلق منقضی (>۲۴ ساعت)
        try:
            punish = v24_store()["punish"]
            for pk, p in list(punish.items()):
                if isinstance(p, dict) and not p.get("done") and not p.get("expired"):
                    created = float(p.get("ts", 0) or 0)
                    if created and (time.time() - created) > 24 * 3600:
                        p["expired"] = True
                        fixes.append(f"punish-expire:{pk}")
        except Exception:
            pass
        # ۶) بانک‌ها: هیچ بانکی None یا پر از موارد خالی نباشد
        for key, bank in list(BANKS.items()):
            if not isinstance(bank, list):
                BANKS[key] = []
                fixes.append(f"bank-reset:{key}")
            else:
                before = len(bank)
                bank[:] = [x for x in bank if isinstance(x, str) and x.strip()]
                if len(bank) != before:
                    fixes.append(f"bank-clean:{key}:{before}->{len(bank)}")
        if fixes:
            save_data(force=True)
    except Exception as exc:
        try:
            print(f"ApexRival data-doctor warning: {exc!r}")
        except Exception:
            pass
    return fixes


