GENDER_ICONS = {"male": "👦 پسر", "female": "👧 دختر"}


def onboarding_needed(uid: int) -> bool:
    u = DATA["users"].get(user_key(uid))
    if not isinstance(u, dict):
        return True
    return not (u.get("gender") and u.get("age"))


def adult_allowed(uid: int) -> bool:
    """دروازه‌ی ۱۸+: یک‌بار برای همیشه تایید می‌شود و در داده می‌ماند."""
    u = get_user(uid)
    return bool(u.get("adult_ok", False))


def group_adult_ok(chat_id: int, uid: int) -> bool:
    """حالت ۱۸+ گروه: کاربر باید تایید کرده باشد؛ کوچک‌ترها هرگز."""
    if not adult_allowed(uid):
        return False
    g = get_group(chat_id)
    return bool(g.get("adult_mode", False))


async def cmd_start(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """نقطه‌ی ورود: آنبوردینگ ترکیبی + دیپ‌لینک‌ها (دوئل و ...)."""
    msg = update.message
    user = update.effective_user
    if msg is None or user is None:
        return
    uid = int(user.id)
    args = list(getattr(context, "args", None) or [])

    # --- دیپ‌لینک دوئل: /start duel-<code> ---
    if args and str(args[0]).startswith("duel-"):
        try:
            code = int(str(args[0]).split("-", 1)[1])
        except Exception:
            code = 0
        if code:
            await duel_handle_deep_link(update, context, uid, code)
            return

    # --- دیپ‌لینک‌های نسخه ۲: pv-<code> / ref-<uid> / tour ---
    if args:
        try:
            if await adv_deep_link(update, context, uid, str(args[0])):
                return
        except Exception:
            pass

    get_user(uid, user.first_name)

    # پاک کردن پیام /start در گروه (اگر مجاز است)
    if update.effective_chat and update.effective_chat.type in ("group", "supergroup"):
        if chat_cfg(int(update.effective_chat.id)).get("delcmd", True):
            await safe_delete(msg)
        else:
            await msg.reply_text("🎮 برای شروع، در چت خصوصی من /start بزن.", parse_mode=ParseMode.HTML)
        return

    if onboarding_needed(uid):
        text = (
            f"🎉 <b>سلام {escape(user.first_name)}!</b>\n"
            "به <b>ApexRival</b> خوش اومدی — میدونِ جنگ گروهی تو! ⚔️\n\n"
            "برای شروع فقط دو چیز کوچیک لازم دارم:"
        )
        markup = kb([
            [btn(GENDER_ICONS["male"], "ON|GENDER|male"), btn(GENDER_ICONS["female"], "ON|GENDER|female")],
        ])
        await msg.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        return

    # خوش‌آمد دوباره
    await show_private_home(update, context, uid, fresh_message=True)


async def onb_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    data = str(query.data or "")
    uid = int(query.from_user.id)
    parts = data.split("|")

    if parts[1] == "GENDER":
        g = parts[2] if len(parts) > 2 else ""
        if g not in ("male", "female"):
            await safe_answer_query(query)
            return
        u = get_user(uid, query.from_user.first_name)
        u["gender"] = g
        save_data()
        await safe_answer_query(query, "ثبت شد ✅")
        text = (
            f"{'👦' if g == 'male' else '👧'} عالیه!\n\n"
            "حالا سن‌ت چنده؟ (برای محافظت بخش ۱۸+ لازم است)"
        )
        markup = kb([
            [btn("🐣 کمتر از ۱۸", "ON|AGE|minor"), btn("🦅 ۱۸ یا بیشتر", "ON|AGE|adult")],
        ])
        await safe_edit(query, text, markup)
        return

    if parts[1] == "AGE":
        adult = parts[2] == "adult" if len(parts) > 2 else False
        u = get_user(uid, query.from_user.first_name)
        u["age"] = 18 if adult else 14
        if adult:
            u["adult_ok"] = True
        save_data()
        if adult:
            await safe_answer_query(query, "حله! 🔓")
            text = (
                "🔓 <b>دروازه‌ی ۱۸+ باز شد</b>\n"
                "موضوع 🔞 فقط در گروه‌هایی فعال است که بزرگسالان اجازه‌اش را داده باشند.\n\n"
                "به جمع ما خوش اومدی! 🎉"
            )
        else:
            await safe_answer_query(query, "ثبت شد 🐣")
            text = (
                "🛡 <b>حالت ایمن فعال شد</b>\n"
                "موضوع‌های ۱۸+ برایت هرگز نمایش داده نمی‌شود و این تصمیم قابل تغییر نیست.\n\n"
                "به جمع ما خوش اومدی! 🎉"
            )
        await safe_edit(query, text, kb([[btn("🎮 شروع کن", "H|HOME")]]))
        return

    await safe_answer_query(query)


