def active_game(chat_id: int) -> dict | None:
    g = get_group(chat_id)
    gid = g.get("active_game")
    if not gid:
        return None
    game = DATA.get("games", {}).get(str(gid))
    if isinstance(game, dict) and str(game.get("status")) == "active":
        return game
    return None


def touch_game(game: dict) -> None:
    game["last_activity"] = now_ts()


def make_game(chat_id: int, leader: int, name: str) -> dict:
    gid = f"g{chat_id}_{now_ts()}_{random.randint(100, 999)}"
    group = get_group(chat_id)
    game = {
        "id": gid,
        "chat_id": int(chat_id),
        "leader_id": int(leader),
        "leader_name": str(name),
        "players": [int(leader)],
        "ready": [],
        "status": "active",
        "phase": "lobby",
        "round": 0,
        "turn_number": 0,
        "turn_index": 0,
        "turn_order": [],
        "current_questioner": None,
        "round_scores": {},
        "used_content": [],
        "v7_used_prompts_global": [],
        "v7_used_penalties": [],
        "pending_penalties": {},
        "names": {str(leader): str(name)},
        "settings": dict(group.get("settings", {})),
        "started_at": 0,
        "last_activity": now_ts(),
        "invite_token": gid,
        "lobby_locked": False,
    }
    with LOCK:
        DATA["games"][gid] = game
        group["active_game"] = gid
    return game


def lobby_text(game: dict) -> str:
    players = game.get("players", [])
    ready = [int(x) for x in game.get("ready", [])]
    group = get_group(int(game["chat_id"]))
    mn = int(group.get("min_players", 2))
    lines = []
    for uid in players:
        mark = " ✅" if uid in ready else " ⏳"
        lines.append(f"• {mention_user(uid, name_of(uid, game))}{mark}")
    return (
        f"⚔️ <b>لابی {BOT_NAME}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👑 سرگروه: {mention_user(int(game['leader_id']), game.get('leader_name') or name_of(int(game['leader_id'])))}\n\n"
        f"👥 بازیکنان ({fmt_num(len(players))}/{fmt_num(int(group.get('max_players', 20)))}):\n"
        + "\n".join(lines)
        + f"\n\n🚦 حداقل بازیکن: <b>{fmt_num(mn)}</b>"
    )


def lobby_markup(game: dict, uid: int) -> InlineKeyboardMarkup:
    players = [int(x) for x in game.get("players", [])]
    ready = [int(x) for x in game.get("ready", [])]
    is_leader = int(uid) == int(game.get("leader_id", 0))
    rows = []
    if uid in players:
        if uid in ready:
            rows.append([btn("⏳ لغو آماده‌باش", "L|UNREADY")])
        else:
            rows.append([btn("✅ آماده‌ام", "L|READY")])
        rows.append([btn("🚪 خروج از بازی", "L|LEAVE")])
    else:
        if not game.get("lobby_locked"):
            rows.append([btn("➕ پیوستن به بازی", "L|JOIN")])
        else:
            rows.append([btn("🔒 لابی قفل است", "L|NOP")])
    if is_leader:
        can_start = len(players) >= int(get_group(int(game["chat_id"])).get("min_players", 2))
        rows.append([
            btn("🚀 شروع بازی" if can_start else f"🚀 شروع ({fmt_num(len(players))}/{fmt_num(int(get_group(int(game['chat_id'])).get('min_players', 2)))})", "L|START"),
        ])
        if len(players) >= 3:
            rows.append([
                btn("🔐 قفل لابی" if not game.get("lobby_locked") else "🔓 باز کردن لابی", "L|LOCK"),
            ])
            # اخراج و انتقال سرگروهی
            rows.append([btn("🦵 اخراج بازیکن", "L|KICK"), btn("👑 انتقال سرگروهی", "L|HOST")])
        rows.append([btn("❌ لغو بازی", "L|CANCEL")])
    return kb(rows)


async def lobby_refresh(update_or_none, context, game: dict, query=None, chat_id: int = 0) -> None:
    """به‌روزرسانی پنل لابی (ویرایش همان پیام)."""
    try:
        if query is not None:
            await safe_edit(query, lobby_text(game), lobby_markup(game, int(query.from_user.id)))
            return
        cid = int(chat_id or game.get("chat_id", 0))
        if cid:
            await context.bot.send_message(cid, lobby_text(game), parse_mode=ParseMode.HTML,
                                           reply_markup=lobby_markup(game, 0))
    except Exception as exc:
        audit("lobby_refresh_error", 0, int(game.get("chat_id", 0) or 0), repr(exc)[:200])


async def cmd_apex(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """ساخت لابی در گروه."""
    msg = update.message
    user = update.effective_user
    chat = update.effective_chat
    if msg is None or user is None or chat is None:
        return
    if chat.type not in ("group", "supergroup"):
        # در خصوصی: منوی خانه
        if not onboarding_needed(int(user.id)):
            await show_private_home(update, context, int(user.id), fresh_message=True)
        else:
            await cmd_start(update, context)
        return
    uid = int(user.id)
    if is_banned(uid) and not is_admin(uid):
        await msg.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
        return
    if onboarding_needed(uid):
        try:
            link = f"https://t.me/{(await context.bot.get_me()).username}?start=x"
            await msg.reply_text(
                "👤 اول باید یک بار ثبت‌نام کنی!\n"
                "به چت خصوصی من برو و /start بزن، بعد برگرد 👇",
                parse_mode=ParseMode.HTML,
                reply_markup=kb([[InlineKeyboardButton("📩 ثبت‌نام در چت خصوصی", url=link)]]),
            )
        except Exception:
            await msg.reply_text("👤 اول به چت خصوصی من /start بزن و ثبت‌نام کن.")
        return

    game = active_game(int(chat.id))
    if game:
        # بازی فعال وجود دارد؛ پنل بازی را نشان بده
        if str(game.get("status")) == "active" and game.get("phase") in ("topic", "playing", "question"):
            await game_send_turn_card(context, game)
        else:
            await context.bot.send_message(int(chat.id), lobby_text(game), parse_mode=ParseMode.HTML,
                                           reply_markup=lobby_markup(game, uid))
        return

    game = make_game(int(chat.id), uid, user.first_name)
    get_group(int(chat.id))["created_games"] = int(get_group(int(chat.id)).get("created_games", 0)) + 1
    save_data(force=True)
    audit("lobby_create", uid, int(chat.id))
    await context.bot.send_message(int(chat.id), lobby_text(game), parse_mode=ParseMode.HTML,
                                   reply_markup=lobby_markup(game, uid))


async def lobby_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None or query.message is None:
        return
    data = str(query.data or "")
    action = data.split("|")[1] if len(data.split("|")) > 1 else ""
    uid = int(query.from_user.id)
    chat = query.message.chat
    if chat.type not in ("group", "supergroup"):
        await safe_answer_query(query, "این دکمه فقط در گروه کار می‌کند.")
        return
    chat_id = int(chat.id)
    game = active_game(chat_id)
    if game is None:
        await safe_answer_query(query, "این لابی دیگر فعال نیست. با /apex جدید بساز. 🔄")
        try:
            await safe_edit(query, "🪦 این لابی بسته شده است. با /apex یک لابی تازه بساز.")
        except Exception:
            pass
        return

    players = [int(x) for x in game.get("players", [])]
    is_leader = uid == int(game.get("leader_id", 0))

    if action == "JOIN":
        if game.get("lobby_locked"):
            await safe_answer_query(query, "🔒 لابی قفل است!", True)
            return
        if uid in players:
            await safe_answer_query(query, "قبلاً داخل بازی هستی 🙂")
            return
        group = get_group(chat_id)
        maxp = int(group.get("max_players", 20))
        if len(players) >= maxp:
            await safe_answer_query(query, f"ظرفیت تکمیل است ({fmt_num(maxp)} نفر).", True)
            return
        # قفل مجازات: بازیکنِ در حال مجازات نمی‌تواند وارد شود
        if punishment_blocks_join(uid):
            await safe_answer_query(query, "⚖️ اول مجازاتت را تمام کن!", True)
            return
        # گیت عضویت کانال (قفل دوم ورود) — بازگردانی از نسخه‌ی اصلی
        membership = await channel_membership(uid, force=False, bot=context.bot)
        if membership is False:
            await safe_answer_query(query, "📢 برای پیوستن، اول عضو کانال شو!", True)
            await gate_notice(query, uid, context)
            return
        game["players"].append(uid)
        game["names"][str(uid)] = query.from_user.first_name or name_of(uid)
        touch_game(game)
        save_data()
        await safe_answer_query(query, f"خوش آمدی {escape(query.from_user.first_name or '')} 🎉")
        await lobby_refresh(None, context, game, query=query)
        return

    if uid not in players and action not in ("NOP",):
        await safe_answer_query(query, "تو داخل این بازی نیستی! اول پیوستن بزن.", True)
        return

    if action == "READY":
        if uid not in [int(x) for x in game.get("ready", [])]:
            game["ready"].append(uid)
        touch_game(game)
        save_data()
        await safe_answer_query(query, "آماده‌باش ثبت شد ✅")
        await lobby_refresh(None, context, game, query=query)
        return

    if action == "UNREADY":
        game["ready"] = [int(x) for x in game.get("ready", []) if int(x) != uid]
        touch_game(game)
        save_data()
        await safe_answer_query(query, "لغو شد ⏳")
        await lobby_refresh(None, context, game, query=query)
        return

    if action == "LEAVE":
        await lobby_remove_player(context, game, uid, query)
        return

    if action == "LOCK":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند لابی را قفل کند.", True)
            return
        game["lobby_locked"] = not bool(game.get("lobby_locked"))
        touch_game(game)
        save_data()
        await safe_answer_query(query, "🔒 لابی قفل شد" if game["lobby_locked"] else "🔓 لابی باز شد")
        await lobby_refresh(None, context, game, query=query)
        return

    if action == "KICK":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند اخراج کند.", True)
            return
        others = [p for p in players if p != uid]
        if not others:
            await safe_answer_query(query, "کسی برای اخراج نیست.")
            return
        rows = []
        for p in others:
            rows.append([btn(f"🦵 {name_of(p, game)}", f"L|KICK|{p}")])
        rows.append([btn("⬅️ برگشت به لابی", "L|REFRESH")])
        await safe_answer_query(query)
        await safe_edit(query, f"🦵 <b>چه کسی اخراج شود؟</b>\n(دکمه را بزن)", kb(rows))
        return

    if action == "KICKACT" or (action == "KICK" and len(data.split("|")) > 2):
        try:
            target = int(data.split("|")[2])
        except Exception:
            target = 0
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه!", True)
            return
        if target and target in [int(x) for x in game.get("players", [])]:
            await lobby_remove_player(context, game, target, query, kicked=True)
        return

    if action == "HOST":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند سرگروهی را منتقل کند.", True)
            return
        others = [p for p in players if p != uid]
        if not others:
            await safe_answer_query(query, "کسی برای انتقال نیست.")
            return
        rows = []
        for p in others:
            rows.append([btn(f"👑 {name_of(p, game)}", f"L|HOSTX|{p}")])
        rows.append([btn("⬅️ برگشت به لابی", "L|REFRESH")])
        await safe_answer_query(query)
        await safe_edit(query, "👑 <b>سرگروهی به چه کسی منتقل شود؟</b>", kb(rows))
        return

    if action == "HOSTX":
        try:
            target = int(data.split("|")[2])
        except Exception:
            target = 0
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه!", True)
            return
        if target and target in players:
            game["leader_id"] = target
            game["leader_name"] = name_of(target, game)
            touch_game(game)
            save_data()
            await safe_answer_query(query, "سرگروهی منتقل شد 👑")
            await context.bot.send_message(chat_id,
                                           f"👑 سرگروهی به {mention_user(target, name_of(target, game))} منتقل شد!",
                                           parse_mode=ParseMode.HTML)
            await lobby_refresh(None, context, game, query=query)
        return

    if action == "CANCEL":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند بازی را لغو کند.", True)
            return
        game["status"] = "finished"
        game["finish_reason"] = "cancelled"
        get_group(chat_id)["active_game"] = None
        save_data(force=True)
        audit("lobby_cancel", uid, chat_id)
        await safe_answer_query(query, "بازی لغو شد ❌")
        await safe_edit(query, "❌ <b>بازی لغو شد.</b>\nبرای شروع دوباره: /apex")
        return

    if action == "REFRESH":
        await safe_answer_query(query)
        await lobby_refresh(None, context, game, query=query)
        return

    if action == "START":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند بازی را شروع کند.", True)
            return
        group = get_group(chat_id)
        mn = max(2, int(group.get("min_players", 2)))
        if len(players) < mn:
            await safe_answer_query(query, f"حداقل {fmt_num(mn)} نفر لازم است!", True)
            return
        # گیت عضویت کانال — بازبینی همه‌ی بازیکنان قبل از شروع (مثل نسخه‌ی اصلی)
        if channel_gate_enabled():
            current, removed, errors = [], [], []
            for p in players:
                m = await channel_membership(int(p), force=True, bot=context.bot)
                if m is True:
                    current.append(int(p))
                elif m is False:
                    removed.append(int(p))
                else:
                    errors.append(int(p))
            if errors:
                await safe_answer_query(query, "⚠️ عضویت یکی از بازیکنان قابل بررسی نیست. فعلاً بازی شروع نشد.", True)
                return
            if removed:
                game["players"] = current
                game["ready"] = [int(x) for x in game.get("ready", []) if int(x) in current]
                for pid in removed:
                    game.get("names", {}).pop(str(pid), None)
                touch_game(game)
                save_data(force=True)
                removed_names = ", ".join(name_of(pid, game) for pid in removed[:8])
                try:
                    await query.message.reply_text(
                        f"🚫 این افراد به دلیل خارج بودن از کانال از لابی حذف شدند: {escape(removed_names)}",
                        parse_mode=ParseMode.HTML,
                    )
                except Exception:
                    pass
                if len(current) < mn:
                    await safe_answer_query(query, f"بعد از حذف، حداقل {fmt_num(mn)} نفر لازم است!", True)
                    await lobby_refresh(None, context, game, query=query)
                    return
                players = current
        await game_start(context, game, query)
        return

    if action == "NOP":
        await safe_answer_query(query)
        return

    await safe_answer_query(query)


async def lobby_remove_player(context, game: dict, uid: int, query=None, kicked: bool = False) -> None:
    players = [int(x) for x in game.get("players", [])]
    if uid not in players:
        await safe_answer_query(query, "تو داخل بازی نیستی.")
        return
    players.remove(uid)
    game["players"] = players
    game["ready"] = [int(x) for x in game.get("ready", []) if int(x) != uid]
    chat_id = int(game.get("chat_id", 0))
    label = name_of(uid, game)
    if kicked:
        await context.bot.send_message(chat_id, f"🦵 {mention_user(uid, label)} از بازی اخراج شد.", parse_mode=ParseMode.HTML)
    else:
        await context.bot.send_message(chat_id, f"🚪 {mention_user(uid, label)} بازی را ترک کرد.", parse_mode=ParseMode.HTML)
    if not players:
        game["status"] = "finished"
        game["finish_reason"] = "empty"
        get_group(chat_id)["active_game"] = None
        save_data(force=True)
        await safe_answer_query(query, "بازی به دلیل نبود بازیکن بسته شد.")
        try:
            await safe_edit(query, "🪦 بازی به دلیل خالی شدن بسته شد.")
        except Exception:
            pass
        return
    if int(game.get("leader_id", 0)) == uid:
        game["leader_id"] = players[0]
        game["leader_name"] = name_of(players[0], game)
        await context.bot.send_message(chat_id, f"👑 سرگروه جدید: {mention_user(players[0], game['leader_name'])}", parse_mode=ParseMode.HTML)
    touch_game(game)
    save_data()
    await safe_answer_query(query, "خارج شدی 🚪" if not kicked else "اخراج شد 🦵")
    if str(game.get("status")) == "lobby" and query is not None:
        await lobby_refresh(None, context, game, query=query)


# ================================================================
#  موتور بازی — شروع، نوبت، سوال، جواب، پاداش
# ================================================================

def current_questioner(game: dict) -> int | None:
    try:
        return int(game["current_questioner"])
    except Exception:
        return None


def advance_turn(game: dict) -> int | None:
    """نوبت را یکی جلو می‌برد؛ None یعنی بازی تمام شده."""
    order = [int(x) for x in game.get("turn_order", [])]
    alive = [p for p in order if p in [int(x) for x in game.get("players", [])]]
    if not alive:
        return None
    idx = int(game.get("turn_index", 0) or 0) % len(alive)
    game["turn_index"] = idx + 1
    game["turn_number"] = int(game.get("turn_number", 0)) + 1
    # هر دورِ کامل، round زیاد می‌شود (موتور گرما)
    if (int(game.get("turn_number", 0)) % max(1, len(alive))) == 0:
        game["round"] = int(game.get("round", 0)) + 1
    game["current_questioner"] = alive[idx]
    game["phase"] = "topic"
    game.pop("reply_prompt", None)
    game.pop("selected_mode", None)
    touch_game(game)
    try:
        daily_tick(game, alive[idx])
    except Exception:
        pass
    return alive[idx]


def turn_announcement(game: dict, questioner: int) -> str:
    label = MODE_LABELS.get(str(game.get("selected_mode")), "")
    heat = game_heat(game)
    return (
        f"🎤 <b>نوبتِ پرسشگری</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"{mention_user(int(questioner), name_of(int(questioner), game))}، وسط میدانی!\n\n"
        f"۱) یک موضوع انتخاب کن\n"
        f"۲) بازیکن هدف را انتخاب کن\n"
        f"۳) سوال خودکار از بانک {fmt_num(BANKS_TOTAL)} سوالی می‌آید\n\n"
        f"🌡 گرمای فعلی بازی: <b>{heat_chip(heat)}</b>"
    )


def turn_markup(game: dict, viewer_uid: int) -> InlineKeyboardMarkup:
    q = current_questioner(game)
    if q is None:
        return kb([[btn("📊 وضعیت بازی", "G|STATUS")]])
    if int(viewer_uid) == int(q):
        rows = []
        pair = []
        off = set(topics_off())
        for key, label in MODE_ORDER:
            if key in off and key not in ("truth", "dare"):
                continue
            if key == "adult" and not get_group(int(game["chat_id"])).get("adult_mode", False):
                continue
            pair.append(btn(label, f"G|MODE|{key}"))
            if len(pair) == 2:
                rows.append(pair)
                pair = []
        if pair:
            rows.append(pair)
        # آیتم‌های هدف فعلی (نسخه ۲) — روی کارت نوبت
        try:
            _rp = game.get("reply_prompt") or {}
            _tgt = int(_rp.get("target_uid", 0) or 0)
            _inv = inventory(_tgt) if _tgt else {}
            _item_btns = []
            if int(_inv.get("changeq", 0) or 0) + int(_inv.get("reroll", 0) or 0) > 0:
                _item_btns.append(btn(f"🔄 تغییر سوال ({fmt_num(int(_inv.get('changeq', 0) or 0) + int(_inv.get('reroll', 0) or 0))})", "G|ITEM|changeq"))
            if int(_inv.get("skipdare", 0) or 0) + int(_inv.get("pass", 0) or 0) > 0:
                _item_btns.append(btn(f"⏭ رد کردن ({fmt_num(int(_inv.get('skipdare', 0) or 0) + int(_inv.get('pass', 0) or 0))})", "G|ITEM|skipdare"))
            if _item_btns:
                rows.append(_item_btns)
        except Exception:
            pass
        rows.append([btn("🎲 تغییر نوبت", "G|SKIP"), btn("ℹ️ راهنما", "G|HELP")])
        rows.append([btn("📊 امتیازها", "G|SCORES"), btn("🏁 پایان بازی", "G|END")])
    else:
        rows = [
            [btn("📊 وضعیت نوبت", "G|STATUS")],
            [btn("📊 امتیازها", "G|SCORES")],
            [btn("🏁 پایان بازی", "G|END")],
        ]
    return kb(rows)


async def game_send_turn_card(context, game: dict) -> None:
    """کارت نوبت جدید را در گروه می‌فرستد."""
    q = current_questioner(game)
    if q is None:
        return
    chat_id = int(game.get("chat_id", 0))
    try:
        await context.bot.send_message(
            chat_id,
            turn_announcement(game, int(q)),
            parse_mode=ParseMode.HTML,
            reply_markup=turn_markup(game, int(q)),
        )
    except Exception as exc:
        audit("turn_send_error", 0, chat_id, repr(exc)[:200])


async def game_start(context, game: dict, query=None) -> None:
    """شروع بازی از لابی."""
    chat_id = int(game.get("chat_id", 0))
    players = [int(x) for x in game.get("players", [])]
    random.shuffle(players)
    game["turn_order"] = players
    game["turn_index"] = 0
    game["turn_number"] = 0
    game["round"] = 0
    game["status"] = "active"
    game["phase"] = "topic"
    game["started_at"] = now_ts()
    game["round_scores"] = {str(p): 0 for p in players}
    for p in players:
        get_user(p)["games"] = int(get_user(p).get("games", 0)) + 1
    # تیم‌ها (اگری فعال باشد)
    try:
        if chat_cfg(chat_id).get("teams", True) and len(players) >= 4:
            teams_build(chat_id, players)
    except Exception:
        pass
    save_data(force=True)
    audit("game_start", int(game.get("leader_id", 0)), chat_id)
    roster = "\n".join(f"• {mention_user(p, name_of(p, game))}" for p in players)
    text = (
        "🚀 <b>بازی شروع شد!</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👥 بازیکنان ({fmt_num(len(players))}):\n{roster}\n\n"
        "🎯 ترتیب نوبت‌ها تصادفی انتخاب شد."
    )
    try:
        if query is not None:
            await safe_answer_query(query, "بازی شروع شد! 🚀")
            await safe_edit(query, text, kb([[btn("🎤 دیدن نوبت", "G|TURN")]]))
        else:
            await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML)
    except Exception:
        pass
    nxt = advance_turn(game)
    save_data(force=True)
    if nxt is not None:
        await game_send_turn_card(context, game)


def game_home_text(game: dict) -> str:
    q = current_questioner(game)
    heat = game_heat(game)
    scores = game.get("round_scores", {})
    players = [int(x) for x in game.get("players", [])]
    top = sorted(players, key=lambda p: -int(scores.get(str(p), 0)))[:3]
    medals = ["🥇", "🥈", "🥉"]
    board = "\n".join(
        f"{medals[i]} {mention_user(p, name_of(p, game))} · ⭐ {fmt_num(int(scores.get(str(p), 0)))}"
        for i, p in enumerate(top) if int(scores.get(str(p), 0)) > 0
    ) or "هنوز امتیازی ثبت نشده."
    return (
        f"🎮 <b>وضعیت بازی</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"🎤 پرسشگر فعلی: {mention_user(int(q), name_of(int(q), game)) if q else '—'}\n"
        f"🔄 شماره نوبت: <b>{fmt_num(int(game.get('turn_number', 0)) + 1)}</b>\n"
        f"🌡 گرما: <b>{heat_chip(heat)}</b>\n\n"
        f"🏆 <b>برترین‌های این بازی</b>\n{board}"
    )


def game_home_markup(game: dict, viewer_uid: int) -> InlineKeyboardMarkup:
    return turn_markup(game, viewer_uid)


async def game_show_panel(update: Update, context: ContextTypes.DEFAULT_TYPE, game: dict, uid: int) -> None:
    chat_id = int(game.get("chat_id", 0))
    try:
        await context.bot.send_message(chat_id, game_home_text(game), parse_mode=ParseMode.HTML,
                                       reply_markup=game_home_markup(game, uid))
    except Exception:
        pass


async def game_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None or query.message is None:
        return
    data = str(query.data or "")
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else ""
    uid = int(query.from_user.id)
    chat = query.message.chat
    chat_id = int(chat.id)
    game = active_game(chat_id)
    if game is None:
        await safe_answer_query(query, "بازی فعالی در این گروه نیست. با /apex بساز. 🔄")
        return

    if action == "ITEM":
        item = parts[2] if len(parts) > 2 else ""
        if not item:
            await safe_answer_query(query)
            return
        await adv_game_item(update, context, game, item, query)
        return

    if action == "TURN" or action == "STATUS":
        await safe_answer_query(query)
        q = current_questioner(game)
        if q is None:
            await safe_edit(query, game_home_text(game), game_home_markup(game, uid))
            return
        await safe_edit(query, turn_announcement(game, int(q)), turn_markup(game, uid))
        return

    if action == "MODE":
        q = current_questioner(game)
        if q is None or int(q) != uid:
            await safe_answer_query(query, "فقط پرسشگر فعلی می‌تواند موضوع را انتخاب کند.", True)
            return
        mode = parts[2] if len(parts) > 2 else ""
        if mode not in MODE_LABELS:
            await safe_answer_query(query, "موضوع نامعتبر است.")
            return
        if mode == "adult":
            if not get_group(chat_id).get("adult_mode", False):
                await safe_answer_query(query, "حالت ۱۸+ در این گروه فعال نیست.", True)
                return
        game["selected_mode"] = mode
        game["phase"] = "target"
        touch_game(game)
        save_data()
        await safe_answer_query(query, f"{MODE_LABELS[mode]} انتخاب شد")
        await game_show_targets(query, game, mode)
        return

    if action == "TARGET":
        q = current_questioner(game)
        if q is None or int(q) != uid:
            await safe_answer_query(query, "فقط پرسشگر فعلی می‌تواند هدف را انتخاب کند.", True)
            return
        try:
            target = int(parts[2])
        except Exception:
            target = 0
        if not target or target not in [int(x) for x in game.get("players", [])]:
            await safe_answer_query(query, "این بازیکن دیگر در بازی نیست.")
            return
        mode = str(game.get("selected_mode") or "truth")
        # محافظت بزرگسال
        if mode == "adult" and not adult_allowed(target):
            await safe_answer_query(query, "هدف، سن خود را تایید نکرده است! 🛡", True)
            return
        # قفل مجازات
        if punishment_blocks_turn(target):
            await safe_answer_query(query, "⚖️ این بازیکن در حال انجام مجازات است!", True)
            return
        await game_ask_question(context, game, int(q), target, mode, query)
        return

    if action == "SCORES":
        await safe_answer_query(query)
        await game_show_scores(query, game)
        return

    if action == "HELP":
        await safe_answer_query(query)
        text = (
            f"{breadcrumb('بازی', 'راهنما')}\n\n"
            + card("ℹ️ چطور بازی کنیم؟",
                   "۱) نوبت فعلی یک نفر مشخص می‌شود.",
                   "۲) همان نفر یک حالت را انتخاب می‌کند.",
                   "۳) سپس یک بازیکن از لیست انتخاب می‌کند.",
                   "۴) ربات سوال را کاملاً تصادفی می‌سازد.",
                   "۵) هدف باید با Reply به همان پیام جواب بدهد.",
                   "۶) بعد از ثبت جواب، نوبت به نفر بعدی می‌رسد.",
                   "🔞 حالت بالغ فقط با تایید سن باز است؛ سوال‌هایش بر اساس جنسیت پاسخ‌دهنده ساخته می‌شوند.",
                   "☠️ حکم‌ها کاملاً تصادفی هستند.")
        )
        await safe_edit(query, text, kb([nav_row("G|TURN")]))
        return

    if action == "SKIP":
        q = current_questioner(game)
        if q is None or int(q) != uid:
            await safe_answer_query(query, "👑 فقط پرسشگر فعلی می‌تواند نوبت را رد کند.", True)
            return
        game.pop("reply_prompt", None)
        nxt = advance_turn(game)
        save_data(force=True)
        await safe_answer_query(query, "نوبت رد شد 🎲")
        if nxt is not None:
            await safe_edit(query, turn_announcement(game, int(nxt)), turn_markup(game, int(nxt)))
        return

    if action == "END":
        q = current_questioner(game)
        is_leader = uid == int(game.get("leader_id", 0))
        if not (is_leader or is_admin(uid)):
            await safe_answer_query(query, "فقط سرگروه می‌تواند بازی را تمام کند.", True)
            return
        await end_game_flow(context, game, query, reason="manual")
        return

    await safe_answer_query(query)


async def game_show_targets(query, game: dict, mode: str) -> None:
    q = current_questioner(game)
    players = [int(x) for x in game.get("players", [])]
    others = [p for p in players if p != q]
    # حذف بازیکنان قفل‌شده توسط مجازات از لیست هدف
    others = [p for p in others if not punishment_blocks_turn(p)]
    rows = []
    for p in others:
        icon = gender_icon(p)
        rows.append([btn(f"{icon} {name_of(p, game)}", f"G|TARGET|{p}")])
    rows.append([btn("🔙 انتخاب موضوع", "G|TURN")])
    await safe_edit(query,
                    f"{breadcrumb('بازی', 'انتخاب هدف')}\n\n"
                    + card(f"🎯 {MODE_LABELS.get(mode, mode)} — هدف را انتخاب کن",
                           "پرسشگر عزیز، حالا نوبت انتخاب قربانی است! 😈"),
                    kb(rows))


async def game_ask_question(context, game: dict, questioner: int, target: int, mode: str, query=None) -> None:
    chat_id = int(game.get("chat_id", 0))
    # گاهی به‌جای سوال، حکم یا رویداد یا باس‌راند صادر می‌شود
    special = None
    settings = game.get("settings", {})
    roll = random.random()
    if roll < 0.10 and settings.get("allow_random_events", True):
        special = "event"
    elif roll < 0.16 and settings.get("allow_boss", True):
        special = "boss"
    elif roll < 0.26 and mode in ("dare", "truth") and settings.get("allow_duel", True):
        special = "penalty"

    if special == "penalty":
        await game_show_penalty(context, game, target, questioner, query)
        return
    if special == "boss":
        await game_boss_round(context, game, questioner, query)
        return
    if special == "event":
        await game_random_event(context, game, questioner, query)
        return

    question = pick_question(game, mode, target)
    heat = game_heat(game)
    text = (
        f"🎤 پرسشگر: {mention_user(questioner, name_of(questioner, game))}\n"
        f"🎯 هدف: {mention_user(target, name_of(target, game))}\n"
        f"📂 موضوع: <b>{MODE_LABELS.get(mode, mode)}</b> · 🌡 {heat_chip(heat)}\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"<b>{escape(question)}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"✍️ {mention_user(target, name_of(target, game))}، با <b>Reply به همین پیام</b> جواب بده!"
    )
    footer = ads_footer(chat_id, "question")
    if footer:
        text += "\n\n" + footer
    try:
        m = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=adv_item_markup(game, target))
        game["phase"] = "question"
        game["reply_prompt"] = {
            "message_id": m.message_id,
            "questioner_uid": int(questioner),
            "target_uid": int(target),
            "mode": mode,
            "expires": time.time() + int(settings.get("penalty_deadline", 300) or 300) + 600,
            "responders": [],
            "sent_ts": time.time(),
        }
        # آمار موضوع برای پروفایل
        try:
            st = get_user(target).setdefault("stats", {})
            if mode in st:
                st[mode] = int(st.get(mode, 0)) + 1
        except Exception:
            pass
        touch_game(game)
        save_data(force=True)
        if query is not None:
            await safe_answer_query(query)
            try:
                await safe_delete(query.message)
            except Exception:
                pass
    except Exception as exc:
        audit("question_send_error", questioner, chat_id, repr(exc)[:200])


async def game_show_penalty(context, game: dict, target: int, questioner: int, query=None) -> None:
    chat_id = int(game.get("chat_id", 0))
    penalty = pick_penalty(game)
    settings = game.get("settings", {})
    deadline = int(settings.get("penalty_deadline", 300) or 300)
    text = (
        f"☠️ <b>حکم صادر شد!</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"🎯 محکوم: {mention_user(target, name_of(target, game))}\n"
        f"⚖️ حکم: <b>{escape(penalty)}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"⏳ مهلت: <b>{fmt_num(deadline // 60)} دقیقه</b>\n"
        f"✅ بعد از انجام، با <b>Reply به همین پیام</b> تایید کن (+۴ XP و +۲ سکه)"
    )
    footer = ads_footer(chat_id, "question")
    if footer:
        text += "\n\n" + footer
    try:
        m = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=adv_item_markup(game, target))
        game["phase"] = "question"
        game["pending_penalties"][str(target)] = {
            "text": penalty,
            "ts": now_ts(),
            "deadline": deadline,
            "done": False,
            "skipped": False,
            "source": "game",
        }
        game["reply_prompt"] = {
            "message_id": m.message_id,
            "questioner_uid": int(questioner),
            "target_uid": int(target),
            "mode": "penalty",
            "kind": "penalty",
            "expires": time.time() + deadline + 300,
            "responders": [],
            "sent_ts": time.time(),
        }
        touch_game(game)
        save_data(force=True)
        if query is not None:
            await safe_answer_query(query)
            try:
                await safe_delete(query.message)
            except Exception:
                pass
    except Exception as exc:
        audit("penalty_send_error", questioner, chat_id, repr(exc)[:200])


async def game_boss_round(context, game: dict, questioner: int, query=None) -> None:
    chat_id = int(game.get("chat_id", 0))
    challenge = random.choice(BOSS_CHALLENGES)
    await safe_answer_query(query, "👑 Boss Round!")
    try:
        await context.bot.send_message(
            chat_id,
            "👑 <b>BOSS ROUND!</b>\n━━━━━━━━━━━━━━━━━━\n"
            f"{escape(challenge)}\n\n"
            "اولین نفری که چالش را انجام دهد پاداش می‌گیرد! 🏃",
            parse_mode=ParseMode.HTML,
        )
        for p in [int(x) for x in game.get("players", [])]:
            get_user(p)["boss"] = int(get_user(p).get("boss", 0)) + 1
        touch_game(game)
        save_data()
    except Exception:
        pass


async def game_random_event(context, game: dict, questioner: int, query=None) -> None:
    chat_id = int(game.get("chat_id", 0))
    title, desc = random.choice(RANDOM_EVENTS)
    players = [int(x) for x in game.get("players", [])]
    await safe_answer_query(query, "✨ رویداد ویژه!")
    try:
        await context.bot.send_message(
            chat_id,
            f"✨ <b>رویداد تصادفی: {escape(title)}</b>\n━━━━━━━━━━━━━━━━━━\n{escape(desc)}",
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass
    if title.startswith("💰") and players:
        for p in random.sample(players, k=min(3, len(players))):
            add_coins(p, 3, name_of(p, game))
    elif title.startswith("🛡") and players:
        lucky = random.choice(players)
        grant_item(lucky, "shield", 1)
    touch_game(game)
    save_data()


REPLY_REWARDS = {"truth": (6, 2), "dare": (7, 3), "mind": (5, 2), "scenario": (6, 2),
                 "flirty": (7, 2), "adult": (8, 3)}


def reward_player(game: dict, uid: int, xp: int, coins: int, win: bool = False, loss: bool = False, reason: str = "") -> None:
    """پاداش مقاوم‌شده: همیشه round_scores موجود، همیشه ذخیره امن."""
    try:
        if isinstance(game, dict):
            game.setdefault("round_scores", {})
    except Exception:
        pass
    try:
        adv_track(int(uid), "answer", {"win": win, "loss": loss, "reason": str(reason)[:30]})
    except Exception:
        pass
    try:
        settings = game.get("settings", {}) if isinstance(game, dict) else {}
        xmult = max(1, int(settings.get("xp_multiplier", 1) or 1))
        cmult = max(1, int(settings.get("coins_multiplier", 1) or 1))
    except Exception:
        xmult, cmult = 1, 1
    add_xp(uid, int(xp), name_of(uid, game), xmult)
    add_coins(uid, int(coins), name_of(uid, game), cmult)
    if win:
        u = get_user(uid)
        u["wins"] = int(u.get("wins", 0)) + 1
        u["streak"] = int(u.get("streak", 0)) + 1
        u["best_streak"] = max(int(u.get("best_streak", 0)), int(u.get("streak", 0)))
        check_achievements(uid)
    if loss:
        u = get_user(uid)
        u["losses"] = int(u.get("losses", 0)) + 1
        u["streak"] = 0
    try:
        if isinstance(game, dict):
            scores = game.setdefault("round_scores", {})
            scores[str(uid)] = int(scores.get(str(uid), 0)) + int(xp)
    except Exception:
        pass


async def handle_game_reply(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """موتور پاسخ: جواب‌های Reply شده به سوال/حکم را می‌خواند."""
    msg = update.message
    if not msg or not msg.reply_to_message or not msg.text:
        return False
    chat = update.effective_chat
    if chat is None or chat.type not in ("group", "supergroup"):
        return False
    game = active_game(int(chat.id))
    if not game or str(game.get("status")) != "active":
        return False
    prompt = game.get("reply_prompt")
    if not isinstance(prompt, dict):
        return False
    if int(prompt.get("message_id", -1)) != int(msg.reply_to_message.message_id):
        return False
    if time.time() > float(prompt.get("expires", 0)):
        game.pop("reply_prompt", None)
        save_data(force=True)
        try:
            await msg.reply_text("⌛ این نوبت تمام شده است؛ نوبت بعدی را از منوی بازی دنبال کنید.")
        except Exception:
            pass
        return True
    uid = int(update.effective_user.id)
    target = prompt.get("target_uid")
    if target is None:
        return False
    target = int(target)
    if uid != target and not is_admin(uid):
        try:
            await msg.reply_text(f"🎯 فعلاً نوبت {mention_user(target, name_of(target, game))} است.", parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return True
    if uid in {int(x) for x in prompt.get("responders", [])}:
        try:
            await msg.reply_text("✅ پاسخ تو قبلاً برای این نوبت ثبت شده است.")
        except Exception:
            pass
        return True
    prompt.setdefault("responders", []).append(uid)
    kind = str(prompt.get("mode") or prompt.get("kind") or "truth")

    # --- تکمیل حکم: پاداش کوچک، بدون پیشروی نوبت ---
    if kind == "penalty":
        pending = game.get("pending_penalties", {}).get(str(uid))
        if pending and not pending.get("done") and not pending.get("skipped"):
            pending["done"] = True
            pending["completed_at"] = now_ts()
            add_xp(uid, 4, name_of(uid, game))
            add_coins(uid, 2, name_of(uid, game))
            if str(pending.get("source", "")).startswith("🤫"):
                get_user(uid)["missions"] = int(get_user(uid).get("missions", 0)) + 1
        game.pop("reply_prompt", None)
        touch_game(game)
        save_data(force=True)
        try:
            await msg.reply_text("✅ <b>حکم انجام شد و ثبت شد.</b>\n🎁 +۴ XP و +۲ سکه", parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return True

    xp, coins = REPLY_REWARDS.get(kind, (5, 2))
    reward_player(game, uid, xp, coins, win=True, reason=f"Turn Reply:{kind}")
    questioner = int(prompt.get("questioner_uid", current_questioner(game) or uid))
    add_xp(questioner, 2, name_of(questioner, game), 1)
    try:
        game.setdefault("round_scores", {})[str(questioner)] = int(game.setdefault("round_scores", {}).get(str(questioner), 0)) + 2
    except Exception:
        pass
    game.pop("reply_prompt", None)
    next_q = advance_turn(game)
    save_data(force=True)
    try:
        await msg.reply_text(
            f"✅ <b>پاسخ ثبت شد!</b>\n\n"
            f"🎯 {mention_user(uid, name_of(uid, game))} پاسخ نوبت را داد.\n"
            f"🎤 {mention_user(questioner, name_of(questioner, game))}، سوال شما با موفقیت جواب داده شد.\n"
            f"🎁 پاسخ‌دهنده: +{fmt_num(xp)} XP و +{fmt_num(coins)} سکه\n"
            f"⭐ پرسشگر: +۲ XP",
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass
    if next_q is not None:
        await game_send_turn_card(context, game)
    return True


async def game_show_scores(query, game: dict) -> None:
    rows = []
    entries = []
    for uid in game.get("players", []):
        score = int(game.get("round_scores", {}).get(str(uid), 0))
        entries.append((score, int(uid)))
    entries.sort(key=lambda x: (-x[0], name_of(x[1], game)))
    for i, (score, uid) in enumerate(entries, 1):
        rows.append(f"<b>{fmt_num(i)}</b> · {mention_user(uid, name_of(uid, game))} · ⭐ {fmt_num(score)}")
    await safe_edit(query,
                    f"{breadcrumb('بازی', 'امتیازها')}\n\n" + card("🏆 Leaderboard", *(rows or ["هنوز امتیازی ثبت نشده."])),
                    kb([[btn("↻ تازه‌سازی", "G|SCORES"), btn("🔙 نوبت", "G|TURN")]]))


async def cmd_apexend(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    chat = update.effective_chat
    user = update.effective_user
    if msg is None or chat is None or user is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🏁 این دستور فقط داخل گروه کار می‌کند.")
        return
    game = active_game(int(chat.id))
    if game is None:
        await msg.reply_text("فعلاً بازی فعالی در این گروه نیست.")
        return
    if int(user.id) != int(game.get("leader_id", 0)) and not is_admin(int(user.id)):
        await msg.reply_text("فقط سرگروه می‌تواند بازی را تمام کند.")
        return
    await end_game_flow(context, game, reason="manual")


async def end_game_flow(context, game: dict, query=None, reason: str = "manual") -> None:
    try:
        await adv_on_game_end(game)
    except Exception:
        pass
    chat_id = int(game.get("chat_id", 0))
    game["status"] = "finished"
    game["finish_reason"] = str(reason)
    game["finished_at"] = now_ts()
    scores = game.get("round_scores", {})
    players = [int(x) for x in game.get("players", [])]
    ranked = sorted(players, key=lambda p: -int(scores.get(str(p), 0)))
    # آمار پایان بازی
    for p in players:
        u = get_user(p)
        u["games"] = max(0, int(u.get("games", 0)) - 1) + 1  # بدون تغییر (شروع هم شمرده شد)
    if ranked:
        reward_player(game, ranked[0], 10, 5, win=True, reason="game_win")
        for p in ranked[1:]:
            reward_player(game, p, 3, 1, reason="game_end")
    get_group(chat_id)["active_game"] = None
    try:
        game_ended_stats(game)
    except Exception:
        pass
    save_data(force=True)
    audit("game_end", 0, chat_id, reason)
    medals = ["🥇", "🥈", "🥉"]
    podium = "\n".join(
        f"{medals[i]} {mention_user(p, name_of(p, game))} · ⭐ {fmt_num(int(scores.get(str(p), 0)))}"
        for i, p in enumerate(ranked[:3]) if int(scores.get(str(p), 0)) > 0
    ) or "امتیازی ثبت نشد."
    text = (
        "🏁 <b>بازی تمام شد!</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"{podium}\n\n"
        "🎉 ممنون از بازیِ شما! برای دور جدید: /apex"
    )
    try:
        await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML)
        if query is not None:
            await safe_answer_query(query, "بازی تمام شد 🏁")
    except Exception:
        pass


# -----------------------------
#  نگهبان نوبت (Stall Guard) + بازی گیرکرده (Stuck Recovery)
# -----------------------------
async def stall_guard_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    """هر ۳ دقیقه: بازی‌های گیرکرده را پیدا کن، یادآوری بده یا رد کن."""
    try:
        cfgs: dict[int, dict] = {}
        for gid, game in list(DATA.get("games", {}).items()):
            if not isinstance(game, dict) or str(game.get("status")) != "active":
                continue
            chat_id = int(game.get("chat_id", 0))
            if chat_id not in cfgs:
                cfgs[chat_id] = anti_abuse_cfg(chat_id)
            cfg = cfgs[chat_id]
            if not cfg.get("stall", True):
                continue
            prompt = game.get("reply_prompt")
            smin = max(3, int(cfg.get("smin", 12)))
            try:
                sent = game.get("_q_sent_ts", 0)
                reminded = game.get("_q_reminded", False)
                if not sent and isinstance(prompt, dict):
                    sent = float(prompt.get("sent_ts", 0) or 0) or 0
                if not sent:
                    continue
                elapsed = time.time() - float(sent)
                if elapsed > smin * 60 and not reminded:
                    target = prompt.get("target_uid")
                    if target:
                        try:
                            await context.bot.send_message(
                                chat_id,
                                f"⏳ {mention_user(int(target), name_of(int(target), game))} هنوز منتظر جواب تو هستیم! 🙏",
                                parse_mode=ParseMode.HTML,
                            )
                        except Exception:
                            pass
                    game["_q_reminded"] = True
                    save_data()
                elif elapsed > (smin + 6) * 60:
                    # رد خودکار نوبت
                    game.pop("reply_prompt", None)
                    game.pop("_q_reminded", None)
                    nxt = advance_turn(game)
                    save_data(force=True)
                    try:
                        await context.bot.send_message(chat_id, "⏭ نوبت معطل مانده خودکار رد شد.", parse_mode=ParseMode.HTML)
                    except Exception:
                        pass
                    if nxt is not None:
                        await game_send_turn_card(context, game)
            except Exception:
                continue
    except Exception as exc:
        audit("stall_guard_error", 0, 0, repr(exc)[:200])


async def stuck_recovery_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    """بازی‌های لابی‌مانده یا بی‌نوبت را بازیابی می‌کند."""
    try:
        for gid, game in list(DATA.get("games", {}).items()):
            if not isinstance(game, dict) or str(game.get("status")) != "active":
                continue
            phase = str(game.get("phase", ""))
            started = float(game.get("started_at", 0) or 0)
            auto_min = int(game.get("settings", {}).get("auto_end_minutes", 90) or 90)
            # بازی خیلی قدیمی → پایان خودکار
            if started and (time.time() - started) > auto_min * 60:
                await end_game_flow(context, game, reason="auto-timeout")
                continue
            # بازی فعال بدون پرسشگر → نوبت جدید
            if phase in ("topic", "playing") and current_questioner(game) is None:
                nxt = advance_turn(game)
                save_data(force=True)
                if nxt is not None:
                    await game_send_turn_card(context, game)
                continue
            # بازی فعال بدون بازیکن زنده → پایان
            if not [p for p in game.get("players", []) if p]:
                await end_game_flow(context, game, reason="empty")
    except Exception as exc:
        audit("stuck_recovery_error", 0, 0, repr(exc)[:200])


