def teams_entry(chat_id: int) -> dict:
    e = v20_store()["teams"].get(group_key(int(chat_id)))
    if isinstance(e, dict) and str(e.get("date", "")) == day_key():
        return e
    return {}


def teams_build(chat_id: int, players: list) -> dict:
    """قرعه‌ی متعادل تیم قرمز/آبی بر اساس XP (مارپیچ)."""
    ranked = sorted([int(p) for p in players], key=lambda p: -int(get_user(p).get("xp", 0)))
    red, blue = [], []
    for i, p in enumerate(ranked):
        (red if i % 2 == 0 else blue).append(p)
    entry = {
        "date": day_key(),
        "red": red,
        "blue": blue,
        "points": {"red": 0, "blue": 0},
        "ts": now_ts(),
    }
    v20_store()["teams"][group_key(int(chat_id))] = entry
    save_data()
    return entry


def team_credit(uid: int, xp: int) -> None:
    """امتیاز سایه‌ای تیم: XP هر عضو به تیمش هم اضافه می‌شود."""
    try:
        if int(xp) <= 0:
            return
        e = teams_entry(0)
        # جستجو در همه‌ی گروه‌های امروز
        teams = v20_store()["teams"]
        today = day_key()
        for gk, entry in teams.items():
            if not isinstance(entry, dict) or str(entry.get("date", "")) != today:
                continue
            for color in ("red", "blue"):
                if int(uid) in [int(x) for x in entry.get(color, [])]:
                    pts = entry.setdefault("points", {})
                    pts[color] = int(pts.get(color, 0)) + int(xp)
                    return
    except Exception:
        pass


def teams_text(chat_id: int) -> str:
    e = teams_entry(chat_id)
    if not e:
        return (
            "🤝 <b>تیم‌های رقابتی</b>\n━━━━━━━━━━━━━━━━━━\n"
            "برای این گروه هنوز تیمی ساخته نشده است.\n"
            "تیم‌ها به‌صورت خودکار هنگام شروع بازی (۴ نفر به بالا) ساخته می‌شوند."
        )
    def side(color, emoji):
        members = [int(x) for x in e.get(color, [])]
        if not members:
            return f"{emoji} <b>تیم {('قرمز' if color=='red' else 'آبی')}</b>: —"
        names = "، ".join(mention_user(p, name_of(p)) for p in members)
        return f"{emoji} <b>تیم {('قرمز' if color=='red' else 'آبی')}</b>: {names}"
    r = int(e.get("points", {}).get("red", 0))
    b = int(e.get("points", {}).get("blue", 0))
    return (
        "🤝 <b>تیم‌های رقابتی</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"{side('red', '🔴')}\n{side('blue', '🔵')}\n\n"
        f"⚔️ امتیاز: قرمز <b>{fmt_num(r)}</b> — آبی <b>{fmt_num(b)}</b>\n"
        + ("🔴 تیم قرمز جلوتر است!" if r > b else ("🔵 تیم آبی جلوتر است!" if b > r else "⚖️ مساوی!"))
    )


