def daily_entry(chat_id: int) -> dict:
    st = v20_store()["daily"]
    e = st.get(group_key(int(chat_id)))
    if not isinstance(e, dict) or str(e.get("date", "")) != day_key():
        e = {"date": day_key(), "turns": 0, "claimed": False, "players": {}}
        st[group_key(int(chat_id))] = e
    return e


def daily_tick(game: dict, questioner: int) -> None:
    """هر اعلام نوبت، شمارنده‌ی چالش روزانه را زیاد می‌کند."""
    try:
        if not chat_cfg(int(game.get("chat_id", 0))).get("daily", True):
            return
        e = daily_entry(int(game.get("chat_id", 0)))
        e["turns"] = int(e.get("turns", 0)) + 1
        if questioner:
            k = user_key(int(questioner))
            e["players"][k] = int(e.get("players", {}).get(k, 0)) + 1
        if not e.get("claimed") and int(e.get("turns", 0)) >= int(chat_cfg(int(game.get("chat_id", 0))).get("daily_goal", 25)):
            e["claimed"] = True
    except Exception:
        pass


def daily_text(chat_id: int) -> str:
    e = daily_entry(chat_id)
    cfg = chat_cfg(chat_id)
    goal = int(cfg.get("daily_goal", 25))
    turns = int(e.get("turns", 0))
    bar = progress_bar(turns, goal)
    if e.get("claimed"):
        status = "✅ کامل شد — جایزه به همه‌ی بازیکنان فعال رسید!"
    else:
        status = f"⏳ باقی‌مانده: <b>{fmt_num(max(0, goal - turns))}</b> نوبت"
    return (
        "📅 <b>چالش روزانه‌ی گروه</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"🎯 هدف امروز: <b>{fmt_num(goal)}</b> نوبت پرسشگری\n"
        f"📊 پیشرفت: <b>{fmt_num(turns)}/{fmt_num(goal)}</b> {bar}\n"
        f"{status}\n\n"
        "🎁 جایزه: هر بازیکنِ فعال امروز +۸ سکه می‌گیرد."
    )


