LUCK_COOLDOWN = 20 * 3600


async def cmd_apexluck(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    user = update.effective_user
    if msg is None or user is None or not started_or_allowed(update):
        return
    uid = int(user.id)
    st = v21_store()
    last = float(st["luck"].get(user_key(uid), 0) or 0)
    if time.time() - last < LUCK_COOLDOWN:
        remain = int((LUCK_COOLDOWN - (time.time() - last)) / 3600)
        await msg.reply_text(f"⏳ گردونه برای تو تا <b>{fmt_num(max(1, remain))} ساعت</b> دیگر خسته است!", parse_mode=ParseMode.HTML)
        return
    st["luck"][user_key(uid)] = time.time()
    st["stats"]["luck_spins"] = int(st["stats"].get("luck_spins", 0)) + 1
    award_achievement(uid, "v21_lucky_star")
    roll = random.random()
    if roll < 0.05:
        coins, label = 50, "🏆 جایزه‌ی بزرگ!"
    elif roll < 0.25:
        coins, label = 20, "🎉 شانس خوب!"
    elif roll < 0.60:
        coins, label = 10, "✨ نه بد نه خوب"
    else:
        coins, label = 5, "🌱 کمی شانس"
    best = int(st["luck_best"].get(user_key(uid), 0) or 0)
    if coins > best:
        st["luck_best"][user_key(uid)] = coins
    add_coins(uid, coins, user.first_name)
    save_data(force=True)
    await msg.reply_text(
        f"🍀 <b>گردونه‌ی شانس</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"{label}\n🎁 جایزه: <b>+{fmt_num(coins)} سکه</b>\n"
        f"🏅 رکورد تو: <b>{fmt_num(max(best, coins))} سکه</b>\n\n"
        "⏰ دور بعدی: ۲۰ ساعت دیگر",
        parse_mode=ParseMode.HTML,
    )


QUIZ_COOLDOWN = 6 * 3600


async def cmd_apexquiz(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """مسابقه‌ی ریاضی سرعتی — اولین جواب درست +۸ XP."""
    msg = update.message
    user = update.effective_user
    if msg is None or user is None or not started_or_allowed(update):
        return
    uid = int(user.id)
    chat = update.effective_chat
    st = v21_store()
    day = day_key()
    quota = st["quiz_day"].get(day, {})
    if quota.get(user_key(uid)):
        await msg.reply_text("🧮 سهمیه‌ی کوییز امروزت پر شده! فردا دوباره 📅")
        return
    a, b = random.randint(2, 12), random.randint(2, 12)
    op = random.choice(["+", "-", "×"])
    if op == "+":
        answer = a + b
    elif op == "-":
        a, b = max(a, b), min(a, b)
        answer = a - b
    else:
        answer = a * b
    # نمایش LTR برای جلوگیری از به‌هم‌ریختگی راست‌به‌چپ
    lrm = "\u200e"
    qtext = f"<code>{lrm}{a} {op} {b} = ?{lrm}</code>"
    quiz = {
        "chat_id": int(chat.id) if chat else 0,
        "a": a, "b": b, "op": op, "answer": answer,
        "ts": time.time(),
        "by": uid,
        "winner": None,
    }
    context.application.bot_data.setdefault("quizzes", {})[f"q{uid}_{int(time.time())}"] = quiz
    # نشانگر برای موتور پاسخ
    context.application.bot_data["quiz_active"] = quiz
    quota = st["quiz_day"].setdefault(day, {})
    quota[user_key(uid)] = True
    st["stats"]["quizzes"] = int(st["stats"].get("quizzes", 0)) + 1
    save_data()
    await msg.reply_text(
        f"🧮 <b>مسابقه‌ی ریاضی سرعتی!</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"{qtext}\n\n"
        "⚡ اولین جواب درست: <b>+۸ XP</b>\n"
        "⏱ فقط ۶۰ ثانیه وقت داری!",
        parse_mode=ParseMode.HTML,
    )


async def quiz_check_answer(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """بررسی جواب کوییز فعال."""
    msg = update.message
    if msg is None or not msg.text:
        return False
    quiz = context.application.bot_data.get("quiz_active")
    if not isinstance(quiz, dict):
        return False
    if quiz.get("winner") is not None:
        return False
    if time.time() - float(quiz.get("ts", 0)) > 60:
        context.application.bot_data.pop("quiz_active", None)
        return False
    chat = update.effective_chat
    if chat is None or int(chat.id) != int(quiz.get("chat_id", 0)):
        return False
    text = msg.text.strip().replace("٬", "").replace(",", "")
    m = re.fullmatch(r"-?\d+", text)
    if not m:
        return False
    if int(text) != int(quiz.get("answer")):
        try:
            await msg.reply_text("❌ نه! دوباره فکر کن...")
        except Exception:
            pass
        return True
    quiz["winner"] = int(update.effective_user.id)
    context.application.bot_data.pop("quiz_active", None)
    uid = int(update.effective_user.id)
    add_xp(uid, 8, update.effective_user.first_name or "بازیکن")
    award_achievement(uid, "v21_quiz_whiz")
    save_data(force=True)
    try:
        await msg.reply_text(
            f"🧮 <b>درست!</b>\n🎉 {mention_user(uid, update.effective_user.first_name)} برنده‌ی کوییز شد: <b>+۸ XP</b>",
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass
    return True


