async def cmd_apexlove2(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """عشق‌سنج دو نفره — هر دو نفر مخفیانه جواب می‌دهند و نتیجه برای هر دو می‌آید."""
    msg = update.message
    user = update.effective_user
    if msg is None or user is None or not started_or_allowed(update):
        return
    target = getattr(msg.reply_to_message, "from_user", None) if msg.reply_to_message else None
    if target is None:
        await msg.reply_text("💌 عشق‌سنج دو نفره: روی پیام طرف مقابل Reply کن و /apexlove2 بزن. لینک خصوصی برای هر دو ساخته می‌شود!")
        return
    uid, tid = int(user.id), int(target.id)
    if uid == tid:
        await msg.reply_text("😅 عشقِ خودت هم قشنگ است ولی این بازی دو نفره است!")
        return
    st = v24_store()
    code = v24_new_code()
    st["love2"][str(code)] = {
        "a": uid, "b": tid,
        "a_done": False, "b_done": False,
        "a_answers": {}, "b_answers": {},
        "ts": now_ts(),
    }
    st["stats"]["love2"] = int(st["stats"].get("love2", 0)) + 1
    save_data(force=True)
    try:
        me = await context.bot.get_me()
        link_a = f"https://t.me/{me.username}?start=duel-lv{code}a"
        link_b = f"https://t.me/{me.username}?start=duel-lv{code}b"
    except Exception:
        link_a = link_b = ""
    await msg.reply_text(
        "💌 <b>عشق‌سنج دو نفره شروع شد!</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"💜 {mention_user(uid, user.first_name)} و {mention_user(tid, target.first_name)}\n\n"
        "هر دو باید در چت خصوصی ربات به ۴ سوال مخفیانه جواب بدهید.\n"
        "بعد از جواب هر دو، گزارش تطابق برای هر دو نفر ارسال می‌شود. 🤫",
        parse_mode=ParseMode.HTML,
    )
    for link, who in ((link_a, uid), (link_b, tid)):
        if not link:
            continue
        try:
            await context.bot.send_message(
                who,
                f"💌 عشق‌سنج دو نفره فعال شد!\nبا دکمه‌ی زیر شروع کن (۴ سوال مخفیانه):",
                parse_mode=ParseMode.HTML,
                reply_markup=kb([[InlineKeyboardButton("💬 شروع پرسش‌ها", url=link)]]),
            )
        except Exception:
            pass


async def love2_start_for(update: Update, context: ContextTypes.DEFAULT_TYPE, uid: int, code: int, side: str) -> None:
    """شروع پرسش‌های عشق‌سنج دو نفره در چت خصوصی."""
    st = v24_store()
    entry = st["love2"].get(str(code))
    if not isinstance(entry, dict):
        await update.message.reply_text("⌛ این عشق‌سنج منقضی یا ناقص است.")
        return
    done_key = f"{side}_done"
    if entry.get(done_key):
        await update.message.reply_text("✅ تو قبلاً جواب‌هایت را داده‌ای! منتظر طرف دیگر...")
        return
    await love2_ask(update, context, code, side, 0)


async def love2_ask(update: Update, context: ContextTypes.DEFAULT_TYPE, code: int, side: str, idx: int) -> None:
    if idx >= len(LOVE2_QUESTIONS):
        await love2_finish_check(update, context, code)
        return
    _, question = LOVE2_QUESTIONS[idx]
    await update.message.reply_text(
        f"💌 <b>سوال {fmt_num(idx + 1)} از {fmt_num(len(LOVE2_QUESTIONS))}</b> (مخفیانه)\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"<b>{escape(question)}</b>\n\n"
        "✍️ جوابت را همین‌جا بنویس (یک پیام).",
        parse_mode=ParseMode.HTML,
        reply_markup=kb([[btn("⏭ رد کردن این سوال", f"LV2|SKIP|{code}|{side}|{idx}")]]),
    )
    context.application.user_data.setdefault(uid_key(update), {})["love2"] = {
        "code": code, "side": side, "idx": idx,
    }


def uid_key(update: Update) -> int:
    return int(update.effective_user.id) if update.effective_user else 0


async def love2_handle_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """متن جواب‌های عشق‌سنج دو نفره در خصوصی."""
    msg = update.message
    if msg is None or not msg.text:
        return False
    chat = update.effective_chat
    if chat is None or chat.type != "private":
        return False
    sess = context.application.user_data.get(uid_key(update), {}).get("love2")
    if not isinstance(sess, dict):
        return False
    code, side, idx = int(sess.get("code", 0)), str(sess.get("side", "a")), int(sess.get("idx", 0))
    st = v24_store()
    entry = st["love2"].get(str(code))
    if not isinstance(entry, dict):
        context.application.user_data.get(uid_key(update), {}).pop("love2", None)
        return False
    ans_key = f"{side}_answers"
    entry.setdefault(ans_key, {})[str(idx)] = (msg.text or "")[:400]
    save_data()
    nxt = idx + 1
    if nxt >= len(LOVE2_QUESTIONS):
        entry[f"{side}_done"] = True
        save_data(force=True)
        context.application.user_data.get(uid_key(update), {}).pop("love2", None)
        await msg.reply_text("✅ جواب‌هایت ثبت شد! تا طرف مقابل هم تمام کند، صبر کن... 🤝")
        await love2_maybe_finish(context, code)
        return True
    sess["idx"] = nxt
    await love2_ask(update, context, code, side, nxt)
    return True


async def love2_finish_check(update: Update, context: ContextTypes.DEFAULT_TYPE, code: int) -> None:
    await update.message.reply_text("✅ ثبت شد!")
    await love2_maybe_finish(context, code)


async def love2_maybe_finish(context, code: int) -> None:
    st = v24_store()
    entry = st["love2"].get(str(code))
    if not isinstance(entry, dict):
        return
    if not (entry.get("a_done") and entry.get("b_done")):
        return
    a, b = int(entry.get("a", 0)), int(entry.get("b", 0))
    a_ans, b_ans = entry.get("a_answers", {}), entry.get("b_answers", {})
    # امتیاز تطابق: هر جواب مشابه/مکمل، امتیاز
    matches = 0
    for i in range(len(LOVE2_QUESTIONS)):
        ta, tb = str(a_ans.get(str(i), "")), str(b_ans.get(str(i), ""))
        if ta.strip() and tb.strip():
            wa = set(re.findall(r"[\w\u0600-\u06FF]+", ta.lower()))
            wb = set(re.findall(r"[\w\u0600-\u06FF]+", tb.lower()))
            if wa & wb:
                matches += 1
    score = 50 + matches * 12
    lines = []
    for i, (_, q) in enumerate(LOVE2_QUESTIONS):
        ta, tb = str(a_ans.get(str(i), "—")), str(b_ans.get(str(i), "—"))
        lines.append(f"❓ {escape(q)}\n   💜 {escape(ta[:120])}\n   💙 {escape(tb[:120])}")
    text = (
        "💌 <b>نتیجه‌ی عشق‌سنج دو نفره</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"🎯 جواب‌های هم‌سو: <b>{fmt_num(matches)} از {fmt_num(len(LOVE2_QUESTIONS))}</b>\n"
        f"💘 درصد هم‌صدایی: <b>{fmt_num(min(98, score))}٪</b> {progress_bar(min(98, score), 100, 10)}\n\n"
        + "\n\n".join(lines)
    )
    for who in (a, b):
        try:
            await context.bot.send_message(who, text, parse_mode=ParseMode.HTML)
        except Exception:
            pass
    st["love2"].pop(str(code), None)
    save_data(force=True)


