async def cmd_apexwyr(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """می‌کردی؟ — رأی‌گیری زنده با نوار درصد."""
    msg = update.message
    chat = update.effective_chat
    if msg is None or chat is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🤔 «می‌کردی؟» فقط در گروه جواب می‌دهد!")
        return
    question = pick_question({"v7_used_prompts_global": [], "v7_used_penalties": [], "round": 0}, "wouldyou", None)
    # پرسش‌های بانک به شکل «... یا ...» هستند؛ اگر نبود، جدا کن
    if " یا " in question:
        left, right = question.split(" یا ", 1)
    else:
        left, right = question, "همه‌چیز را رها کنی و بروی!"
    poll_id = f"wyr{v24_new_code()}"
    context.application.bot_data.setdefault("wyr", {})[poll_id] = {"a": 0, "b": 0, "voters": {}, "ts": time.time()}
    v24_store()["stats"]["party_games"] = int(v24_store()["stats"].get("party_games", 0)) + 1
    save_data()
    await msg.reply_text(
        "🤔 <b>تو کدوم رو می‌کردی؟</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"🅰️ <b>{escape(left.strip())}</b>\n\nیا\n\n"
        f"🅱️ <b>{escape(right.strip())}</b>",
        parse_mode=ParseMode.HTML,
        reply_markup=kb([
            [btn("🅰️ گزینه اول", f"FY|WYR|{poll_id}|a"), btn("🅱️ گزینه دوم", f"FY|WYR|{poll_id}|b")],
        ]),
    )


async def wyr_vote(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    if len(parts) < 4:
        await safe_answer_query(query)
        return
    poll_id, choice = parts[2], parts[3]
    polls = context.application.bot_data.setdefault("wyr", {})
    poll = polls.get(poll_id)
    if not isinstance(poll, dict):
        await safe_answer_query(query, "این نظرسنجی بسته شده است.")
        return
    uid = int(query.from_user.id)
    voters = poll.setdefault("voters", {})
    if str(uid) in voters:
        await safe_answer_query(query, "رأی‌ات را قبلاً دادی! 🗳")
        return
    voters[str(uid)] = choice
    poll[choice] = int(poll.get(choice, 0)) + 1
    a, b = int(poll.get("a", 0)), int(poll.get("b", 0))
    total = max(1, a + b)
    pa, pb = int(a * 100 / total), 100 - int(a * 100 / total)
    try:
        await query.edit_message_text(
            "🤔 <b>تو کدوم رو می‌کردی؟</b> (زنده!)\n━━━━━━━━━━━━━━━━━━\n"
            f"🅰️ {progress_bar(pa, 100, 8)} <b>{fmt_num(pa)}٪</b> ({fmt_num(a)})\n"
            f"🅱️ {progress_bar(pb, 100, 8)} <b>{fmt_num(pb)}٪</b> ({fmt_num(b)})\n\n"
            "🗳 رأی بده تا نوارها زنده به‌روز شوند!",
            parse_mode=ParseMode.HTML,
            reply_markup=query.message.reply_markup,
        )
        await safe_answer_query(query, "رأی ثبت شد! 🗳")
    except Exception:
        await safe_answer_query(query, "رأی ثبت شد! 🗳")


