async def likely_vote(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    if len(parts) < 4:
        await safe_answer_query(query)
        return
    poll_id, target = parts[2], parts[3]
    polls = context.application.bot_data.setdefault("likely", {})
    poll = polls.get(poll_id)
    if not isinstance(poll, dict):
        await safe_answer_query(query, "این رأی‌گیری بسته شده است.")
        return
    uid = int(query.from_user.id)
    votes = poll.setdefault("votes", {})
    votes[str(uid)] = target
    counts: dict[str, int] = {}
    for v in votes.values():
        counts[v] = counts.get(v, 0) + 1
    top = sorted(counts.items(), key=lambda kv: -kv[1])
    lines = "\n".join(
        f"• {mention_user(int(k), name_of(int(k)))}: <b>{fmt_num(v)} رأی</b> {progress_bar(v, max(1, len(votes)), 8)}"
        for k, v in top
    )
    try:
        await query.edit_message_text(
            "🎯 <b>به احتمال زیاد، کی؟</b> (زنده!)\n━━━━━━━━━━━━━━━━━━\n"
            + (lines or "هنوز رأیی نیامده."),
            parse_mode=ParseMode.HTML,
            reply_markup=query.message.reply_markup,
        )
        await safe_answer_query(query, "رأی ثبت شد! 🗳")
    except Exception:
        await safe_answer_query(query, "رأی ثبت شد! 🗳")


