async def achievements_show(update: Update, context: ContextTypes.DEFAULT_TYPE, query=None) -> None:
    src = query if query is not None else (update.callback_query if update and update.callback_query else None)
    uid = int(src.from_user.id) if src is not None else int(update.effective_user.id if update and update.effective_user else 0)
    user = get_user(uid)
    got = set(user.get("achievements", []))
    xp = int(user.get("xp", 0))
    wins = int(user.get("wins", 0))
    streak = int(user.get("best_streak", 0))
    games = int(user.get("games", 0))
    # گروه‌بندی
    groups = {
        "🏆 برد و بازی": ["first_win", "ten_wins", "streak5", "games20"],
        "💰 ثروت": ["coins100", "xp500"],
        "🎮 ماجراجویی": ["missions10", "boss5", "duels10", "votes10"],
        "✨ نسخه‌ی جدید": ["v18_bank_editor", "v18_custom_author", "v18_quest_done", "v18_heat_master",
                          "v20_team_player", "v20_daily_hero", "v20_heart_giver",
                          "v21_lucky_star", "v21_quiz_whiz", "v21_generous",
                          "v24_punisher", "v24_duelist", "v24_party_soul", "v24_shopaholic", "v24_bank_center"],
    }
    progress_map = {
        "first_win": (wins, 1), "ten_wins": (wins, 10), "streak5": (streak, 5),
        "games20": (games, 20), "coins100": (int(user.get("coins", 0)), 100), "xp500": (xp, 500),
    }
    lines = []
    for gname, keys in groups.items():
        lines.append(f"\n<b>{gname}</b>")
        for k in keys:
            if k not in ACHIEVEMENTS_BASE:
                continue
            name, desc, coins = ACHIEVEMENTS_BASE[k]
            if k in got:
                lines.append(f"✅ {name} — {escape(desc)} <i>(+{fmt_num(coins)}🪙)</i>")
            else:
                cur, goal = progress_map.get(k, (0, 0))
                if goal:
                    lines.append(f"▫️ {name} — {escape(desc)} {progress_bar(cur, goal, 6)} {fmt_num(cur)}/{fmt_num(goal)}")
                else:
                    lines.append(f"▫️ {name} — {escape(desc)}")
    total = sum(1 for k in ACHIEVEMENTS_BASE)
    mine = sum(1 for k in got if k in ACHIEVEMENTS_BASE)
    text = (
        f"🎖 <b>دستاوردهای من</b> — {fmt_num(mine)}/{fmt_num(total)}\n"
        "━━━━━━━━━━━━━━━━━━\n"
        + "\n".join(lines)
    )
    markup = kb([[btn("⬅️ منوی اصلی", "H|HOME")]])
    if query is not None:
        await safe_answer_query(query)
        await safe_edit(query, text, markup)
    elif update is not None and update.message is not None:
        await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)


