THEME_BORDERS = {
    "purple": "🟪🟪🟪🟪🟪🟪🟪🟪🟪🟪",
    "gold": "🟨🟨🟨🟨🟨🟨🟨🟨🟨🟨",
    "fire": "🟥🟥🟥🟥🟥🟥🟥🟥🟥🟥",
    "ocean": "🟦🟦🟦🟦🟦🟦🟦🟦🟦🟦",
    "neon": "🟩🟪🟩🟪🟩🟪🟩🟪🟩🟪",
    "royal": "🟨⬛🟨⬛🟨⬛🟨⬛🟨⬛",
}


def profile_text(uid: int) -> str:
    u = get_user(uid)
    level = int(u.get("level", 1))
    xp = int(u.get("xp", 0))
    floor_xp = (level - 1) * 100
    title = str(u.get("title") or title_for(xp))
    theme = str(u.get("theme") or "")
    border = THEME_BORDERS.get(theme, "▬▬▬▬▬▬▬▬▬▬")
    inv = u.get("inventory", {})
    inv_count = sum(1 for v in inv.values() if int(v) > 0)
    stats = u.get("stats", {})
    fav = ""
    try:
        fav_key, fav_n = sorted(
            [(k, int(v)) for k, v in stats.items() if int(v) > 0],
            key=lambda kv: -kv[1])[0]
        fav = f"{MODE_LABELS.get(fav_key, fav_key)} ({fmt_num(fav_n)} بار)"
    except Exception:
        fav = "—"
    created = u.get("created_at", 0)
    age = ""
    if created:
        days = max(1, (now_ts() - int(created)) // 86400)
        age = f"{fmt_num(days)} روز با ما"
    ach_count = sum(1 for k in u.get("achievements", []) if k in ACHIEVEMENTS_BASE)
    _lines = [
        f"{border}",
        f"🪪 <b>پروفایل {escape(str(u.get('name') or 'بازیکن'))}</b>",
        f"{border}",
        "",
        f"🏷 لقب: <b>{escape(title)}</b>",
        f"🎯 سطح <b>{fmt_num(level)}</b> {progress_bar(xp - floor_xp, 100, 10)} ({fmt_num(xp - floor_xp)}/۱۰۰)",
        f"⭐ XP کل: <b>{fmt_num(xp)}</b>",
        f"🪙 سکه: <b>{fmt_num(int(u.get('coins', 0)))}</b>",
        "",
        f"🎮 بازی‌ها: <b>{fmt_num(int(u.get('games', 0)))}</b> · 🏆 برد: <b>{fmt_num(int(u.get('wins', 0)))}</b> · 💔 باخت: <b>{fmt_num(int(u.get('losses', 0)))}</b>",
        f"🔥 بهترین استریک: <b>{fmt_num(int(u.get('best_streak', 0)))}</b>",
        f"🤝 دوئل‌ها: <b>{fmt_num(int(u.get('duels', 0)))}</b> · 🗳 رأی‌ها: <b>{fmt_num(int(u.get('votes', 0)))}</b>",
        f"🤫 مأموریت‌ها: <b>{fmt_num(int(u.get('missions', 0)))}</b> · 👑 باس‌ها: <b>{fmt_num(int(u.get('boss', 0)))}</b>",
        "",
        f"📚 موضوع محبوب: <b>{fav}</b>",
        f"🎒 کالاها: <b>{fmt_num(inv_count)}</b> · 🎖 دستاوردها: <b>{fmt_num(ach_count)}/{fmt_num(len(ACHIEVEMENTS_BASE))}</b>",
    ]
    if age:
        _lines.append(f"📅 {age}")
    _lines.append("━━━━━━━━━━━━━━━━━━")
    _lines.append(f"📦 ApexRival نسخه {VERSION}")
    return "\n".join(_lines)


async def cmd_apexprofile(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    user = update.effective_user
    if msg is None or user is None:
        return
    if is_banned(int(user.id)) and not is_admin(int(user.id)):
        await msg.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
        return
    target = getattr(msg.reply_to_message, "from_user", None) if msg.reply_to_message else None
    uid = int(target.id) if target else int(user.id)
    await msg.reply_text(profile_text(uid), parse_mode=ParseMode.HTML,
                         reply_markup=kb([[btn("🎖 دستاوردها", "P|ACH"), btn("🛍 فروشگاه", "S|HOME")]]))


async def profile_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    if action == "PROFILE":
        await safe_answer_query(query)
        await safe_edit(query, profile_text(int(query.from_user.id)),
                        kb([[btn("🎖 دستاوردها", "P|ACH"), btn("🛍 فروشگاه", "S|HOME")]]))
        return
    if action == "TOP":
        await safe_answer_query(query)
        await cmd_apextop_fake(query)
        return
    if action == "ACH":
        await achievements_show(update, context, query=query)
        return
    await safe_answer_query(query)


async def cmd_apextop_fake(query) -> None:
    """نمایش رتبه‌بندی داخل پنل (بدون پیام جدید)."""
    weekly = weekly_board(10)
    alltime = sorted(
        [(int(k), int(v.get("xp", 0))) for k, v in DATA.get("users", {}).items() if isinstance(v, dict)],
        key=lambda x: -x[1],
    )[:10]
    wk_lines = "\n".join(
        f"{['🥇','🥈','🥉'][i] if i < 3 else f'{fmt_num(i+1)}.'} {mention_user(u, name_of(u))} · ⭐ {fmt_num(xp)}"
        for i, (u, xp) in enumerate(weekly)
    ) or "هنوز کسی این هفته XP نگرفته."
    at_lines = "\n".join(
        f"{['🥇','🥈','🥉'][i] if i < 3 else f'{fmt_num(i+1)}.'} {mention_user(u, name_of(u))} · ⭐ {fmt_num(xp)}"
        for i, (u, xp) in enumerate(alltime)
    ) or "هنوز کسی بازی نکرده."
    await safe_edit(
        query,
        "🏆 <b>رتبه‌بندی</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"📅 <b>این هفته</b>\n{wk_lines}\n\n♾ <b>همه‌ی زمان‌ها</b>\n{at_lines}",
        kb([[btn("⬅️ منوی اصلی", "H|HOME")]]),
    )


