async def cmd_apexhelp(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    if msg is None:
        return
    text = (
        f"❓ <b>راهنمای کامل {BOT_NAME}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
    )
    for title, cmds in HELP_SECTIONS:
        text += f"\n<b>{title}</b>\n" + "\n".join(escape(c) for c in cmds) + "\n"
