async def cmd_apexpanel(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    user = update.effective_user
    if msg is None or user is None:
        return
    if not is_admin(int(user.id)):
        await msg.reply_text("🚫 این بخش فقط برای ادمین است.")
        return
    await msg.reply_text(admin_home_text(), parse_mode=ParseMode.HTML, reply_markup=admin_home_markup())


async def admin_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    uid = int(query.from_user.id)
    if not is_admin(uid):
        await safe_answer_query(query, "فقط ادمین!", True)
        return
    data = str(query.data or "")
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else ""

    if action == "HOME":
        await safe_answer_query(query)
        await safe_edit(query, admin_home_text(), admin_home_markup())
        return

    if action == "STATS":
        users = DATA.get("users", {})
        total_xp = sum(int(u.get("xp", 0)) for u in users.values() if isinstance(u, dict))
        total_coins = sum(int(u.get("coins", 0)) for u in users.values() if isinstance(u, dict))
        games_all = DATA.get("games", {})
        finished = sum(1 for g in games_all.values() if isinstance(g, dict) and str(g.get("status")) == "finished")
        st24 = v24_store()["stats"]
        await safe_answer_query(query)
        await safe_edit(
            query,
            "📊 <b>آمار کلی</b>\n━━━━━━━━━━━━━━━━━━\n"
            f"👥 کاربران: <b>{fmt_num(len(users))}</b>\n"
            f"⭐ مجموع XP: <b>{fmt_num(total_xp)}</b>\n"
            f"🪙 مجموع سکه: <b>{fmt_num(total_coins)}</b>\n"
            f"🎮 بازی‌های پایان‌یافته: <b>{fmt_num(finished)}</b>\n\n"
            f"🤺 دوئل‌ها: <b>{fmt_num(int(st24.get('duels', 0)))}</b>\n"
            f"⚖️ مجازات‌ها: <b>{fmt_num(int(st24.get('punishments', 0)))}</b>\n"
            f"🎉 بازی‌های مهمانی: <b>{fmt_num(int(st24.get('party_games', 0)))}</b>\n"
            f"🛍 خریدها: <b>{fmt_num(int(st24.get('shop_buys', 0)))}</b>",
            kb([nav_row("A|HOME")]),
        )
        return

    if action == "USERS":
        await admin_users_home(query)
        return
    if action == "USEARCH":
        await admin_users_search(query, parts)
        return
    if action == "UDETAIL":
        try:
            target = int(parts[2])
        except Exception:
            target = 0
        await admin_user_detail(query, target)
        return
    if action in ("UBAN", "UUNBAN", "UXP", "UCOIN", "UDM"):
        await admin_user_action(query, parts)
        return

    if action == "ADS":
        await admin_ads_home(query)
        return
    if action in ("ADADD", "ADDEL", "ADTOG", "ADFREQ"):
        await admin_ads_action(query, parts)
        return

    if action == "BC":
        await admin_bc_home(query)
        return
    if action.startswith("BC"):
        await admin_bc_action(update, context, query, parts)
        return

    if action == "BANK":
        await bank_center_home(query)
        return
    if action.startswith("ED"):
        await editor_callback(update, context, query, parts)
        return
    if action == "EXPORT":
        await bank_export(update, context, query)
        return
    if action == "IMPORT":
        await bank_import_start(update, context, query)
        return

    if action == "DOCTOR":
        fixes = data_doctor()
        await safe_answer_query(query)
        await safe_edit(
            query,
            "🩺 <b>دکتر داده</b>\n━━━━━━━━━━━━━━━━━━\n"
            + ("\n".join(f"• {escape(f)}" for f in fixes) if fixes else "✅ همه‌چیز سالم است! هیچ اصلاحی لازم نبود."),
            kb([nav_row("A|HOME")]),
        )
        return

    if action == "BACKUPS":
        backups = list_backups()[:10]
        lines = [f"• <code>{escape(b.name)}</code> ({fmt_num(b.stat().st_size)} بایت)" for b in backups]
        await safe_answer_query(query)
        await safe_edit(
            query,
            "🗄 <b>بکاپ‌ها</b>\n━━━━━━━━━━━━━━━━━━\n"
            + ("\n".join(lines) if lines else "هنوز بکاپی وجود ندارد."),
            kb([[btn("💾 بکاپ فوری", "A|BKICK")], nav_row("A|HOME")]),
        )
        return
    if action == "BKICK":
        path = backup_data("manual")
        await safe_answer_query(query, "بکاپ گرفته شد ✅" if path else "خطا در بکاپ!", not bool(path))
        return

    if action == "RESET":
        await safe_answer_query(query)
        await safe_edit(
            query,
            "⚠️ <b>ریست کارخانه</b>\n━━━━━━━━━━━━━━━━━━\n"
            "این کار <b>همه‌ی داده‌ها</b> (کاربران، گروه‌ها، بازی‌ها) را پاک می‌کند!\n"
            "قبلش یک بکاپ خودکار گرفته می‌شود.\n\n"
            "مطمئنی؟",
            kb([
                [btn("🔴 بله، پاک کن", "A|RESETYES")],
                [btn("🟢 نه! برگرد", "A|HOME")],
            ]),
        )
        return
    if action == "RESETYES":
        backup_data("before-reset")
        with LOCK:
            DATA.clear()
            DATA.update(default_data())
        save_data(force=True)
        audit("factory_reset", uid)
        await safe_answer_query(query, "ریست کامل شد.")
        await safe_edit(query, "✅ ریست کارخانه انجام شد.\nداده‌ها از صفر شروع می‌شوند.", kb([nav_row("A|HOME")]))
        return

    await safe_answer_query(query)


# -----------------------------
#  مدیریت کاربران
# -----------------------------
USERS_PAGE = 8


async def admin_users_home(query, page: int = 0) -> None:
    users = [(int(k), v) for k, v in DATA.get("users", {}).items() if str(k).lstrip("-").isdigit()]
    users.sort(key=lambda kv: -int(kv[1].get("xp", 0)))
    total = len(users)
    page = max(0, min((total - 1) // USERS_PAGE, page))
    chunk = users[page * USERS_PAGE:(page + 1) * USERS_PAGE]
    rows = []
    for tid, u in chunk:
        ban = "🚫" if u.get("banned") else "🟢"
        rows.append([btn(f"{ban} {u.get('name', '؟')} — ⭐{fmt_num(int(u.get('xp', 0)))}", f"A|UDETAIL|{tid}")])
    nav = []
    if page > 0:
        nav.append(btn("◀️", f"A|USERS|{page-1}"))
    nav.append(btn(f"{fmt_num(page+1)}/{fmt_num(max(1, (total + USERS_PAGE - 1) // USERS_PAGE))}", "A|NOP"))
    if (page + 1) * USERS_PAGE < total:
        nav.append(btn("▶️", f"A|USERS|{page+1}"))
    if nav:
        rows.append(nav)
    rows.append([btn("🔍 جستجو با آیدی", "A|USEARCH")])
    rows.append(nav_row("A|HOME"))
    await safe_answer_query(query)
    await safe_edit(
        query,
        f"👥 <b>مدیریت کاربران</b> ({fmt_num(total)} نفر)\n━━━━━━━━━━━━━━━━━━\n"
        "مرتب‌شده بر اساس XP:",
        kb(rows),
    )


async def admin_users_search(query, parts) -> None:
    await safe_answer_query(query)
    _ADS_INPUT["mode"] = "user_search"
    await safe_edit(
        query,
        "🔍 <b>جستجوی کاربر</b>\n━━━━━━━━━━━━━━━━━━\n"
        "آیدی عددی کاربر را بفرست (مثلاً: <code>123456789</code>)",
        kb([nav_row("A|USERS")]),
    )


class _FakeQuery:
    """شبیه‌ساز CallbackQuery برای پاسخ‌های داخل چت."""
    def __init__(self, query, uid: int):
        self.message = query
        self.from_user = type("U", (), {"id": uid})()

    async def answer(self, text=None, show_alert=False):
        if text:
            try:
                await self.message.reply_text(text)
            except Exception:
                pass


async def admin_user_detail(query, tid: int) -> None:
    u = DATA.get("users", {}).get(str(tid))
    if not isinstance(u, dict):
        await safe_answer_query(query, "کاربر پیدا نشد!", True)
        return
    ban = "🚫 مسدود" if u.get("banned") else "🟢 فعال"
    await safe_answer_query(query)
    await safe_edit(
        query,
        f"👤 <b>جزئیات کاربر</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"🆔 <code>{fmt_num(tid)}</code>\n"
        f"📛 نام: <b>{escape(str(u.get('name', '؟')))}</b>\n"
        f"👫 جنسیت: <b>{'پسر' if u.get('gender') == 'male' else 'دختر' if u.get('gender') == 'female' else '—'}</b>\n"
        f"⭐ XP: <b>{fmt_num(int(u.get('xp', 0)))}</b> · 🎯 سطح: <b>{fmt_num(int(u.get('level', 1)))}</b>\n"
        f"🪙 سکه: <b>{fmt_num(int(u.get('coins', 0)))}</b>\n"
        f"🎮 بازی: <b>{fmt_num(int(u.get('games', 0)))}</b> · 🏆 برد: <b>{fmt_num(int(u.get('wins', 0)))}</b>\n"
        f"🎖 دستاورد: <b>{fmt_num(len(u.get('achievements', [])))}</b>\n"
        f"📍 وضعیت: <b>{ban}</b>",
        kb([
            [btn("🚫 مسدود / آزاد", f"A|UBAN|{tid}"), btn("⭐ XP", f"A|UXP|{tid}")],
            [btn("🪙 سکه", f"A|UCOIN|{tid}"), btn("📩 پیام خصوصی", f"A|UDM|{tid}")],
            nav_row("A|USERS"),
        ]),
    )


async def admin_user_action(query, parts) -> None:
    action = parts[1]
    try:
        tid = int(parts[2])
    except Exception:
        await safe_answer_query(query, "کاربر نامعتبر.", True)
        return
    u = DATA.get("users", {}).get(str(tid))
    if not isinstance(u, dict):
        await safe_answer_query(query, "کاربر پیدا نشد!", True)
        return
    if action == "UBAN":
        u["banned"] = not bool(u.get("banned"))
        save_data(force=True)
        audit("admin_ban", int(query.from_user.id), None, f"target={tid} banned={u['banned']}")
        await safe_answer_query(query, "مسدود شد 🚫" if u["banned"] else "آزاد شد 🟢")
        await admin_user_detail(query, tid)
        return
    # اکشن‌های عددی: منتظر ورودی عددی ادمین
    if action in ("UXP", "UCOIN", "UDM"):
        _ADMIN_USER_INPUT["action"] = action
        _ADMIN_USER_INPUT["target"] = tid
        _ADMIN_USER_INPUT["chat_id"] = int(query.message.chat.id) if query.message else 0
        prompts = {
            "UXP": "⭐ مقدار XP را بفرست (مثبت یا منفی، مثل: <code>50</code> یا <code>-20</code>):",
            "UCOIN": "🪙 مقدار سکه را بفرست (مثبت یا منفی):",
            "UDM": "📩 متن پیام خصوصی به این کاربر را بفرست:",
        }
        await safe_answer_query(query)
        await query.message.reply_text(prompts[action], parse_mode=ParseMode.HTML)
        return
    await safe_answer_query(query)


_ADMIN_USER_INPUT = {"action": "", "target": 0, "chat_id": 0}


