async def bank_import_apply(json_text: str, admin_uid: int) -> str:
    """اعمال ورودی JSON: فقط اضافه‌کردن سوال جدید (merge + dedupe)."""
    try:
        payload = json.loads(json_text)
        if not isinstance(payload, dict):
            return "⚠️ ساختار فایل معتبر نیست (باید object باشد)."
    except Exception as exc:
        return f"⚠️ JSON نامعتبر: {str(exc)[:80]}"
    added = 0
    skipped = 0
    bad = 0
    for key, items in payload.items():
        key = str(key)
        if not isinstance(items, list):
            bad += 1
            continue
        bank = BANKS.setdefault(key, [])
        existing = set(bank)
        for raw in items:
            text = str(raw).strip()
            if not text:
                bad += 1
                continue
            if text in existing:
                skipped += 1
                continue
            bank.append(text)
            existing.add(text)
            added += 1
        # ذخیره‌ی سفارشی‌ها برای ماندگاری بعد از ری‌استارت
        if added:
            store = DATA.setdefault("v18_custom_prompts", {})
            store.setdefault(key, [])
            sset = set(store[key])
            for raw in items:
                text = str(raw).strip()
                if text and text not in sset:
                    store[key].append(text)
    v24_store()["stats"]["imports"] = int(v24_store()["stats"].get("imports", 0)) + 1
    save_data(force=True)
    audit("bank_import", admin_uid, None, f"added={added} skipped={skipped}")
    return (
        f"✅ <b>ورودی اعمال شد</b>\n"
        f"➕ سوال جدید: <b>{fmt_num(added)}</b>\n"
        f"♻️ تکراری (رد شد): <b>{fmt_num(skipped)}</b>\n"
        f"❌ نامعتبر: <b>{fmt_num(bad)}</b>"
    )


# -----------------------------
#  ویرایشگر سوالات
# -----------------------------
EDITOR_PAGE = 8


async def editor_callback(update, context, query, parts) -> None:
    action = parts[1]
    uid = int(query.from_user.id)

    if action == "EDHOME" or action == "HOME":
        rows = []
        for key in sorted(BANKS.keys()):
            off = "🌑" if key in topics_off() else "️"
            rows.append([btn(f"{escape(key)} — {fmt_num(len(BANKS[key]))}", f"ED|BANK|{key}")])
        rows.append(nav_row("A|BANK"))
        await safe_answer_query(query)
        await safe_edit(
            query,
            "✏️ <b>ویرایشگر سوالات</b>\n━━━━━━━━━━━━━━━━━━\n"
            "یک بانک را انتخاب کن:",
            kb(rows),
        )
        return

    if action == "BANK":
        key = parts[2] if len(parts) > 2 else ""
        await editor_bank_page(query, key, 0)
        return

    if action == "PAGE":
        key = parts[2] if len(parts) > 2 else ""
        try:
            page = int(parts[3]) if len(parts) > 3 else 0
        except Exception:
            page = 0
        await editor_bank_page(query, key, page)
        return

    if action == "ADD":
        key = parts[2] if len(parts) > 2 else ""
        await safe_answer_query(query)
        await query.message.reply_text(f"➕ سوال جدید برای بانک <code>{escape(key)}</code> را بفرست:", parse_mode=ParseMode.HTML)
        _ADS_INPUT["mode"] = "bank_add"
        _ADS_INPUT["bank"] = key
        return

    if action == "TOG":
        key = parts[2] if len(parts) > 2 else ""
        off = topics_off()
        if key in off:
            off.remove(key)
        else:
            off.append(key)
        save_data()
        await safe_answer_query(query, "موضوع روشن شد ✅" if key not in off else "موضوع خاموش شد 🌑")
        await editor_callback(update, context, query, ["x", "EDHOME"])
        return

    if action == "DEL":
        key = parts[2] if len(parts) > 2 else ""
        idx = parts[3] if len(parts) > 3 else ""
        try:
            i = int(idx)
            bank = BANKS.get(key, [])
            if key in BANKS_FACTORY and 0 <= i < len(BANKS_FACTORY[key]):
                await safe_answer_query(query, "⛔ سوالات اصلی قفل هستند! (فقط سوالات جدید قابل حذف‌اند)", True)
                return
            if 0 <= i < len(bank):
                text = bank.pop(i)
                v18_disabled = editor_store()["disabled"].setdefault(key, [])
                v18_disabled.append({"h": bank_hash(text), "text": text})
                save_data(force=True)
                await safe_answer_query(query, "حذف شد 🗑")
        except Exception:
            await safe_answer_query(query, "نامعتبر.", True)
        await editor_bank_page(query, key, 0)
        return

    if action == "RESET":
        key = parts[2] if len(parts) > 2 else ""
        if key in BANKS_FACTORY:
            BANKS[key] = list(BANKS_FACTORY[key])
            editor_store()["overrides"].pop(key, None)
            editor_store()["disabled"].pop(key, None)
            DATA.get("v16_custom_prompts", {}).pop(key, None)
            DATA.get("v18_custom_prompts", {}).pop(key, None)
            save_data(force=True)
            apply_bank_admin_changes()
            await safe_answer_query(query, "بانک به حالت کارخانه برگشت ♻️")
        else:
            await safe_answer_query(query, "نامعتبر.", True)
        await editor_callback(update, context, query, ["x", "EDHOME"])
        return

    if action == "EDIT":
        key = parts[2] if len(parts) > 2 else ""
        idx = parts[3] if len(parts) > 3 else ""
        await safe_answer_query(query)
        try:
            i = int(idx)
            bank = BANKS.get(key, [])
            if key in BANKS_FACTORY and 0 <= i < len(BANKS_FACTORY[key]):
                await safe_answer_query(query, "⛔ سوالات اصلی قفل هستند! (قانون طلایی نسخه ۲)", True)
                return
            if 0 <= i < len(bank):
                await query.message.reply_text(
                    f"✏️ متن جدید برای سوال زیر را بفرست:\n\n«{escape(str(bank[i])[:120])}»",
                    parse_mode=ParseMode.HTML,
                )
                _ADS_INPUT["mode"] = "bank_edit"
                _ADS_INPUT["bank"] = key
                _ADS_INPUT["idx"] = i
        except Exception:
            pass
        return

    await safe_answer_query(query)


async def editor_bank_page(query, key: str, page: int) -> None:
    bank = BANKS.get(key, [])
    total = len(bank)
    pages = max(1, (total + EDITOR_PAGE - 1) // EDITOR_PAGE)
    page = max(0, min(pages - 1, page))
    start = page * EDITOR_PAGE
    chunk = bank[start:start + EDITOR_PAGE]
    off = key in topics_off()
    lines = []
    rows = []
    for i, q in enumerate(chunk):
        idx = start + i
        lines.append(f"<b>{fmt_num(idx + 1)}.</b> {escape(str(q)[:90])}")
        rows.append([btn(f"✏️ ویرایش #{fmt_num(idx + 1)}", f"ED|EDIT|{key}|{idx}"),
                     btn(f"🗑 حذف #{fmt_num(idx + 1)}", f"ED|DEL|{key}|{idx}")])
    nav = []
    if page > 0:
        nav.append(btn("◀️", f"ED|PAGE|{key}|{page-1}"))
    nav.append(btn(f"{fmt_num(page+1)}/{fmt_num(pages)}", "ED|NOP"))
    if page + 1 < pages:
        nav.append(btn("▶️", f"ED|PAGE|{key}|{page+1}"))
    if nav:
        rows.append(nav)
    rows.append([btn("➕ سوال جدید", f"ED|ADD|{key}")])
    rows.append([btn("🌑 روشن/خاموش", f"ED|TOG|{key}"), btn("♻️ ریست بانک", f"ED|RESET|{key}")])
    rows.append([btn("⬅️ بانک‌ها", "ED|EDHOME")])
    await safe_answer_query(query)
    await safe_edit(
        query,
        f"✏️ <b>بانک: {escape(key)}</b> — {fmt_num(total)} سوال" + (" (خاموش 🌑)" if off else "") +
        "\n━━━━━━━━━━━━━━━━━━\n" + ("\n".join(lines) if lines else "خالی است."),
        kb(rows),
    )


async def admin_document_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """دریافت فایل JSON برای ورودی بانک."""
    msg = update.message
    user = update.effective_user
    if msg is None or user is None or msg.document is None:
        return False
    if not is_admin(int(user.id)):
        return False
    if _ADS_INPUT.get("mode") != "bank_import":
        return False
    try:
        doc = await msg.document.get_file()
        raw = await doc.download_as_bytearray()
        text = bytes(raw).decode("utf-8", errors="replace")
    except Exception as exc:
        await msg.reply_text(f"⚠️ خواندن فایل ناموفق: {str(exc)[:80]}")
        return True
    result = await asyncio.get_event_loop().run_in_executor(None, bank_import_apply, text, int(user.id))
    await msg.reply_text(result, parse_mode=ParseMode.HTML)
    _ADS_INPUT["mode"] = ""
    return True


async def admin_input_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """ورودی‌های عددی/متنی اکشن‌های کاربر (XP/سکه/DM)."""
    # در admin_text_router ادغام شده است؛ اینجا برای جستجوی آیدی
    return False


