async def home_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    uid = int(query.from_user.id)
    chat = query.message.chat if query.message else None

    if action == "CLOSE":
        await safe_answer_query(query)
        if chat is not None and chat.type in ("group", "supergroup"):
            await safe_edit(query, "✅ پنل بسته شد. برای بازی: /apex")
        else:
            try:
                await query.message.delete()
            except Exception:
                await safe_edit(query, "✅ بسته شد.")
        return

    if action == "GUIDE":
        page = 0
        if len(parts) > 2:
            try:
                page = int(parts[2])
            except Exception:
                page = 0
        await safe_answer_query(query)
        await guide_show(update, context, page, query=query)
        return

    if action == "HOME":
        await safe_answer_query(query)
        if chat is not None and chat.type in ("group", "supergroup"):
            await show_group_menu(update, context, int(chat.id), uid)
            try:
                await query.message.delete()
            except Exception:
                pass
        else:
            await safe_edit(query, private_home_text(uid), private_home_markup(uid))
        return

    await safe_answer_query(query)


