async def love2_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    if parts[1] == "SKIP":
        uid = int(query.from_user.id)
        sess = context.application.user_data.get(uid, {}).get("love2")
        if isinstance(sess, dict):
            code, side, idx = int(sess.get("code", 0)), str(sess.get("side", "a")), int(sess.get("idx", 0))
            entry = v24_store()["love2"].get(str(code))
            if isinstance(entry, dict):
                entry.setdefault(f"{side}_answers", {})[str(idx)] = "—"
                nxt = idx + 1
                if nxt >= len(LOVE2_QUESTIONS):
                    entry[f"{side}_done"] = True
                    save_data(force=True)
                    context.application.user_data.get(uid, {}).pop("love2", None)
                    await safe_answer_query(query, "ثبت شد!")
                    await love2_maybe_finish(context, code)
                    return
                sess["idx"] = nxt
                await love2_ask(update, context, code, side, nxt)
                await safe_answer_query(query)
                return
    await safe_answer_query(query)


