async def route_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """اولویت‌بندی پیام‌های متنی غیر-دستوری."""
    # ۱) ادمین: ویزاردها
    try:
        if await admin_text_router(update, context):
            return
    except Exception:
        pass
    # ۱.۵) نسخه ۲: ورودی ادمین ۲.۰ / بازی خصوصی / راند سرعتی گروه
    try:
        if await adv_text_router(update, context):
            return
    except Exception:
        pass
    # ۲) عشق‌سنج دو نفره (خصوصی)
    try:
        if await love2_handle_text(update, context):
            return
    except Exception:
        pass
    # ۳) دوئل (خصوصی)
    try:
        if await duel_handle_text(update, context):
            return
    except Exception:
        pass
    # ۴) کوییز فعال (خصوصی یا گروه — هر جا کوییز ساخته شده)
    try:
        if await quiz_check_answer(update, context):
            return
    except Exception:
        pass
    chat = update.effective_chat
    if chat is None or chat.type not in ("group", "supergroup"):
        return
    # ۵) جواب نوبت بازی
    try:
        if await handle_game_reply(update, context):
            return
    except Exception:
        pass
    # ۶) تریگرهای متنی گروه
    try:
        await group_text_triggers(update, context)
    except Exception:
        pass


