def profile_v2_text(uid: int) -> str:
    u = get_user(uid)
    xp = int(u.get("xp", 0))
    level = int(u.get("level", 1))
    floor_xp = (level - 1) * 100
    bar = progress_bar(xp - floor_xp, 100)
