#  🔌 سیم‌کشی نهایی نسخه ۲ — روترها، ثبت هندلرها، بوت، دیپ‌لینک‌ها
# ================================================================

async def adv_route_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """روتر واحد کالبک‌های نسخه ۲ (پیشوند ثبت‌شده در route_callback اصلی)."""
    query = update.callback_query
    if query is None:
        return
    data = str(query.data or "")
    prefix = data.split("|")[0] if "|" in data else ""
    try:
        if prefix == "DB":
            uid = int(query.from_user.id)
            await safe_answer_query(query)
            await safe_edit(query, dashboard_text(uid), dashboard_markup(uid))
        elif prefix == "P2":
            await profile_v2_callback(update, context)
        elif prefix == "LB":
            await leaderboard_callback(update, context)
        elif prefix == "MI":
            await missions_callback(update, context)
        elif prefix == "SS":
            await season_callback(update, context)
        elif prefix == "FR":
            await friends_callback(update, context)
        elif prefix == "RV":
            await rivals_callback(update, context)
        elif prefix == "RF":
            await referral_callback(update, context)
        elif prefix == "PV":
            await pv_callback(update, context)
        elif prefix == "GT":
            await gt_callback(update, context)
        elif prefix == "A2":
            await a2_callback(update, context)
        elif prefix == "U2":
            await user_settings_callback(update, context)
        elif prefix == "AI":
            await ai_callback(update, context)
        elif prefix == "NB":
            await notifications_callback(update, context)
        else:
            await safe_answer_query(query)
    except Exception as exc:
        audit("adv_callback_error", int(query.from_user.id), None, f"{data[:40]} {repr(exc)[:150]}")
        await safe_answer_query(query, "خطایی پیش آمد؛ دوباره امتحان کن 🙏")


async def adv_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """مسیر متن‌های نسخه ۲: ورودی ادمین ۲.۰ → پاسخ بازی خصوصی → جواب سرعتی گروه."""
    try:
        if update.effective_chat is None or update.effective_user is None:
            return False
        if update.effective_chat.type == "private":
            # ۱) ورودی‌های پنل مدیریت ۲.۰
            try:
                if await a2_admin_input(update, context):
                    return True
            except Exception:
                pass
            try:
                if await a2_admin_input_extra(update, context):
                    return True
            except Exception:
                pass
            # ۲) پاسخ بازی خصوصی
            try:
                if await pv_handle_answer(update, context):
                    return True
            except Exception:
                pass
        else:
            # ۳) جواب‌های راند سرعتی گروه (Reply به سوال)
            try:
                if await speed_handle_reply(update, context):
                    return True
            except Exception:
                pass
    except Exception:
        pass
    return False


def adv_register_handlers(app) -> None:
    """ثبت هندلرهای جدید (فقط افزایشی)."""
    # گیت حالت نگهداری — قبل از همه (سطح -۹۱)
    try:
        app.add_handler(TypeHandler(Update, adv_maintenance_gate_handler), group=-91)
    except Exception:
        pass
    # ضد سیل دستورها در گروه (قبل از گیت اصلی)
    try:
        app.add_handler(MessageHandler(filters.COMMAND & filters.ChatType.GROUPS, adv_group_flood_guard), group=-89)
    except Exception:
        pass


async def adv_maintenance_gate_handler(update: Update, context) -> None:
    """حالت نگهداری: کاربران عادی متوقف می‌شوند؛ تیم مدیریت رد می‌شود."""
    from telegram.ext import ApplicationHandlerStop
    try:
        if not maintenance_on():
            return
        user = update.effective_user
        if user is not None and perm_level(int(user.id)) >= PERM_MOD:
            return
        cq = update.callback_query
        if cq is not None:
            await safe_answer_query(cq, "🛠 ربات در حالت نگهداری است؛ چند دقیقه دیگر برگرد!", True)
            raise ApplicationHandlerStop()
        msg = update.message
        if msg is not None and str(msg.text or "").startswith("/"):
            chat = update.effective_chat
            m = adv_store()["maintenance"]
            body = str(m.get("msg") or "").strip() or "در حال ارتقا هستیم؛ چند دقیقه دیگر برگرد! 🔄"
            until = float(m.get("until", 0) or 0)
            extra = f"\n⏰ تا {time.strftime('%H:%M', time.localtime(until))}" if until else ""
            if chat is not None:
                try:
                    await context.bot.send_message(int(chat.id),
                        f"🛠 <b>حالت نگهداری</b>\n{escape(body)}{extra}",
                        parse_mode=ParseMode.HTML)
                except Exception:
                    pass
            raise ApplicationHandlerStop()
    except ApplicationHandlerStop:
        raise
    except Exception:
        pass


async def adv_deep_link(update: Update, context, uid: int, arg: str) -> bool:
    """دیپ‌لینک‌های نسخه ۲: pv-<code> | ref-<uid> | tour"""
    try:
        arg = str(arg)
        if arg.startswith("pv-"):
            try:
                code = int(arg.split("-", 1)[1])
            except Exception:
                code = 0
            if code:
                await pv_deep_link(update, context, uid, code)
                return True
        elif arg.startswith("ref-"):
            try:
                inviter = int(arg.split("-", 1)[1])
            except Exception:
                inviter = 0
            if inviter:
                msg_text = referral_apply(uid, inviter)
                if msg_text:
                    user = update.effective_user
                    await update.message.reply_text(msg_text, parse_mode=ParseMode.HTML)
                    get_user(uid, user.first_name if user else None)
                    return True
        elif arg == "tour":
            get_user(uid, update.effective_user.first_name if update.effective_user else None)
            await update.message.reply_text(
                "🚀 <b>تور آشنایی ApexRival</b>",
                parse_mode=ParseMode.HTML,
                reply_markup=kb([[btn("▶️ شروع تور", "AI|TOUR|0")]]))
            return True
    except Exception as exc:
        audit("adv_deeplink_error", int(uid), None, repr(exc)[:120])
    return False


async def adv_post_init(app) -> None:
    """راه‌اندازی نسخه ۲ بعد از بوت: بازیابی جلسات، مهاجرت، سیزون."""
    try:
        fixes = adv_migrate()
        if fixes:
            print(f"ApexRival v2 migration: {len(fixes)} fields ensured (additive only)")
    except Exception as exc:
        print(f"adv migrate warning: {exc!r}")
    try:
        n = await sessions_recovery(app.bot)
        if n:
            print(f"ApexRival v2 recovery: {n} sessions resolved")
    except Exception as exc:
        print(f"adv recovery warning: {exc!r}")
    try:
        season_ensure()
    except Exception:
        pass


async def adv_on_game_end(game: dict) -> None:
    """قلاب پایان بازی گروهی: ماموریت + آمار."""
    try:
        for p in [int(x) for x in game.get("players", [])]:
            adv_track(p, "game", {})
    except Exception:
        pass


def adv_periodic(context) -> None:
    """قلاب نگهداری دوره‌ای نسخه ۲ (در periodic_maintenance اصلی صدا زده می‌شود)."""
    try:
        adv_periodic_maintenance()
    except Exception:
        pass
    try:
        app = getattr(context, "application", None)
        if app is not None:
            app.create_task(adv_resolve_deadline_sessions(context))
    except Exception:
        pass


def build_application() -> Application:
    """ساخت و پیکربندی کامل اپلیکیشن — همه‌ی هندلرها."""
    builder = ApplicationBuilder().token(BOT_TOKEN)
    proxy = os.getenv("PROXY_URL", "").strip()
    if proxy:
        try:
            builder = builder.proxy(proxy).get_updates_proxy(proxy)
        except Exception:
            pass
    app = builder.build()

    # --- دستورات ---
    command_map = {
        "start": cmd_start,
        "apex": cmd_apex,
        "apexend": cmd_apexend,
        "apexhelp": cmd_apexhelp,
        "apexguide": cmd_apexguide,
        "apexabout": cmd_apexabout,
        "apexping": cmd_apexping,
        "apexlive": cmd_apexlive,
        "apextip": cmd_apextip,
        "apexname": cmd_apexname,
        "apexdice": cmd_apexdice,
        "apexcoin": cmd_apexcoin,
        "apex8ball": cmd_apex8ball,
        "apexluck": cmd_apexluck,
        "apexquiz": cmd_apexquiz,
        "apexgift": cmd_apexgift,
        "apexlove": cmd_apexlove,
        "apexlove2": cmd_apexlove2,
        "apexheart": cmd_apexheart,
        "apexbrb": cmd_apexbrb,
        "apexback": cmd_apexback,
        "apexteams": cmd_apexteams,
        "apexdaily": cmd_apexdaily,
        "apexrecap": cmd_apexrecap,
        "apextop": cmd_apextop,
        "apexprofile": cmd_apexprofile,
        "apexpunish": cmd_apexpunish,
        "apexforgive": cmd_apexforgive,
        "apexpunishments": cmd_apexpunishments,
        "apexduel": cmd_apexduel,
        "apexspin": cmd_apexspin,
        "apexwyr": cmd_apexwyr,
        "apexnhie": cmd_apexnhie,
        "apexlikely": cmd_apexlikely,
        "apexsettings": cmd_apexsettings,
        "apexstats": cmd_apexstats,
        "apexid": cmd_apexid,
        "apexpanel": cmd_apexpanel,
        "apexmute": cmd_apexmute,
        "apexunmute": cmd_apexunmute,
        "shop": cmd_shop,
        "skip": cmd_skip_wizard,
        "verify": cmd_verify,
        # --- دستورات نسخه ۲ ---
        "dashboard": cmd_dashboard,
        "missions": cmd_missions,
        "friends": cmd_friends,
        "rivals": cmd_rivals,
        "refer": cmd_refer,
        "season": cmd_season,
        "pv": cmd_pv,
        "tournament": cmd_tournament,
        "survival": cmd_survival,
        "teamwar": cmd_teamwar,
        "panel2": cmd_admin_v2,
        "profile2": cmd_profile_v2,
        "top2": cmd_top_v2,
        # نام‌های آشنای قدیمی
        "profile": cmd_apexprofile,
        "rank": cmd_apextop,
        "help": cmd_apexhelp,
        "about": cmd_apexabout,
        "ping": cmd_apexping,
        "menu": cmd_apex,
        "game": cmd_apex,
        "bazi": cmd_apex,
        "panel": cmd_apexpanel,
    }
    for name, handler in command_map.items():
        app.add_handler(CommandHandler(name, handler))

    # --- کالبک‌ها: یک روتر واحد + محافظ اسپم قبل از همه ---
    app.add_handler(CallbackQueryHandler(route_callback), group=0)

    # --- عضویت ربات در گروه (فعال‌سازی) ---
    app.add_handler(TypeHandler(Update, on_my_chat_member), group=-90)

    # --- خوش‌آمدگویی ---
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, welcome_new_member), group=-89)

    # --- گیت دستورات گروهی (راهنمای دوستانه) ---
    app.add_handler(MessageHandler(filters.COMMAND & filters.ChatType.GROUPS, group_command_gate), group=-88)

    # --- فایل (ورودی بانک ادمین) ---
    app.add_handler(MessageHandler(filters.Document.ALL & filters.ChatType.PRIVATE, admin_document_router), group=-87)

    # --- متن‌های عمومی ---
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, route_text), group=0)

    # --- هندلرهای نسخه ۲ (ضد سیل + گیت نگهداری) ---
    try:
        adv_register_handlers(app)
    except Exception as exc:
        print(f"adv register warning: {exc!r}")

    # --- خطا ---
    app.add_error_handler(error_handler)

    # --- کارهای زمان‌بندی‌شده ---
    try:
        if app.job_queue is not None:
            app.job_queue.run_repeating(periodic_maintenance, interval=180, first=60)
            app.job_queue.run_repeating(backup_job, interval=6 * 3600, first=300)
        else:
            print("ApexRival warning: job_queue unavailable (install python-telegram-bot[job-queue])")
    except Exception as exc:
        print(f"ApexRival job-queue warning: {exc!r}")

    return app


def run_once() -> None:
    """یک اجرای کامل با آماده‌سازی قبل از شروع."""
    # دکتر داده + گزارش اصلاحات
    fixes = data_doctor()
    if fixes:
        print(f"ApexRival data-doctor: {len(fixes)} fixes applied")

    app = build_application()
    app.post_init = post_init
    start_health_server()
    print(f"ApexRival {VERSION} starting | banks={BANKS_TOTAL} prompts | modes={len(MODE_ORDER)} | commands={len(COMMANDS_PRIVATE) + len(COMMANDS_GROUP)}")
    app.run_polling(allowed_updates=Update.ALL_TYPES, drop_pending_updates=True)


def main() -> None:
    """لانچر مقاوم: تا ۵ بار ری‌استارت با فاصله، بعد پیام خروج."""
    # راهنمای دوستانه اگر توکن نیست
    if not BOT_TOKEN:
        print("=" * 62)
        print("  توکن ربات تنظیم نشده است!")
        print("  در Render متغیر محیطی BOT_TOKEN را با توکن BotFather")
        print("  تنظیم کن، یا لوکال این‌طور اجرا کن:")
        print()
        print("      BOT_TOKEN=123456:ABC... ADMIN_ID=12345 python bot.py")
        print()
        print("  ⚠️ ADMIN_ID هم حتماً تنظیم کن تا پنل مدیریتی فعال شود.")
        print("=" * 62)
        raise SystemExit(1)

    max_restarts = 5
    for attempt in range(1, max_restarts + 1):
        try:
            run_once()
            break
        except SystemExit:
            raise
        except KeyboardInterrupt:
            print("ApexRival: خروج دستی.")
            break
        except Exception as exc:
            print(f"ApexRival launcher: fatal error ({exc!r}); restart {attempt}/{max_restarts} in 7s ...")
            if attempt >= max_restarts:
                print("ApexRival launcher: giving up after 5 attempts.")
                raise
            time.sleep(7)


if __name__ == "__main__":
    main()

